} from 'lucide-react';
import { Category } from './types';

export const CATEGORIES: { id: Category; icon: React.ReactNode; description: string }[] = [
  { id: 'Photography', icon: <Camera size={24} />, description: 'Showcase your visual storytelling through stunning galleries.' },
  { id: 'Web Development', icon: <Code size={24} />, description: 'Display code projects, technical skills, and software solutions.' },
  { id: 'Video Editing', icon: <Video size={24} />, description: 'Highlight showreels, motion graphics, and cinematic works.' },
  { id: 'Cooking', icon: <ChefHat size={24} />, description: 'Share recipes, culinary adventures, and professional plating.' },
  { id: 'Painting', icon: <Palette size={24} />, description: 'An online gallery for your fine art, sketches, and digital paintings.' },
  { id: 'Writing', icon: <PenTool size={24} />, description: 'A clean layout for articles, copy, scripts, and literary works.' },
