  github: <Github size={20} />,
  linkedin: <Linkedin size={20} />,
  twitter: <Twitter size={20} />,
  portfolio: <Globe size={20} />,
};

export const INITIAL_DATA = {
  fullName: '',
  tagline: '',
  about: '',
  email: '',
  location: '',
  category: 'Web Development' as Category,
  skills: [],
  projects: [],
  socials: {}
};

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const polishBio = async (bio: string, category: string, name: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `I am a ${category} freelancer named ${name}. Here is my rough draft of my bio: "${bio}". 
                 Please polish this into a professional, engaging, and concise portfolio "About Me" section (around 2-3 sentences). 
                 Return ONLY the polished text.`,
    });
    return response.text?.trim() || bio;
  } catch (error) {
    console.error("Gemini Error:", error);
    return bio;
  }
};

export const generateTagline = async (name: string, category: string, skills: string[]) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a short, punchy, professional tagline for a ${category} freelancer named ${name}. 
                 Key skills: ${skills.join(', ')}. 
                 Maximum 10 words. Return ONLY the tagline.`,
    });
    return response.text?.trim() || `Passionate ${category} professional.`;
  } catch (error) {
    console.error("Gemini Error:", error);
    return `Specializing in ${category}.`;
  }
};

export const suggestProjects = async (category: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `List 3 creative placeholder project titles and short 1-sentence descriptions for a ${category} portfolio.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
            },
            required: ["title", "description"],
          }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    console.error("Gemini Error:", error);
    return [];
  }
};

import React from 'react';
