import React, { useState } from 'react';
import { PortfolioData, Skill, Project } from '../types';
import { Plus, Trash2, Sparkles, Loader2, ArrowRight } from 'lucide-react';
import { polishBio, generateTagline } from '../services/geminiService';

interface EditorFormProps {
  data: PortfolioData;
  onChange: (data: PortfolioData) => void;
  onNext: () => void;
}

const EditorForm: React.FC<EditorFormProps> = ({ data, onChange, onNext }) => {
  const [isPolishing, setIsPolishing] = useState(false);
  const [newSkill, setNewSkill] = useState({ name: '', level: 80 });

  const updateField = (field: keyof PortfolioData, value: any) => {
    onChange({ ...data, [field]: value });
  };

  const updateSocial = (platform: string, value: string) => {
    onChange({ ...data, socials: { ...data.socials, [platform]: value } });
  };

  const handlePolishBio = async () => {
    if (!data.about || !data.fullName) return;
    setIsPolishing(true);
    const polished = await polishBio(data.about, data.category, data.fullName);
    updateField('about', polished);
    setIsPolishing(false);
  };

  const handleMagicTagline = async () => {
    if (!data.fullName) return;
    setIsPolishing(true);
    const tag = await generateTagline(data.fullName, data.category, data.skills.map(s => s.name));
    updateField('tagline', tag);
    setIsPolishing(false);
  };

  const addSkill = () => {
    if (!newSkill.name) return;
    updateField('skills', [...data.skills, newSkill]);
    setNewSkill({ name: '', level: 80 });
  };

  const removeSkill = (index: number) => {
    const newSkills = [...data.skills];
    newSkills.splice(index, 1);
    updateField('skills', newSkills);
  };

  const addProject = () => {
    const proj: Project = {
      id: Date.now().toString(),
      title: 'New Project',
      description: 'Project description goes here...',
      imageUrl: `https://picsum.photos/seed/${Math.random()}/600/400`,
      tags: [data.category]
    };
    updateField('projects', [...data.projects, proj]);
  };

  const updateProject = (id: string, updates: Partial<Project>) => {
    const newProjects = data.projects.map(p => p.id === id ? { ...p, ...updates } : p);
    updateField('projects', newProjects);
  };

  const removeProject = (id: string) => {
    updateField('projects', data.projects.filter(p => p.id !== id));
  };

  return (
    <div className="space-y-12">
      {/* Basic Info */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
          <span className="w-8 h-8 bg-indigo-100 text-indigo-600 rounded-lg flex items-center justify-center text-sm">1</span>
          Basic Information
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-700">Full Name</label>
            <input 
              type="text" 
              value={data.fullName}
              onChange={(e) => updateField('fullName', e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
              placeholder="e.g. Alex Rivera"
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-700">Email Address</label>
            <input 
              type="email" 
              value={data.email}
              onChange={(e) => updateField('email', e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
              placeholder="alex@example.com"
            />
          </div>
          <div className="md:col-span-2 space-y-2">
            <div className="flex justify-between items-center">
              <label className="text-sm font-semibold text-gray-700">Tagline</label>
              <button 
                onClick={handleMagicTagline}
                disabled={isPolishing || !data.fullName}
                className="text-xs font-medium text-indigo-600 hover:text-indigo-700 flex items-center gap-1 disabled:opacity-50"
              >
                {isPolishing ? <Loader2 className="animate-spin" size={12} /> : <Sparkles size={12} />}
                Magic Suggest
              </button>
            </div>
            <input 
              type="text" 
              value={data.tagline}
              onChange={(e) => updateField('tagline', e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
              placeholder="e.g. Capturing moments that last a lifetime"
            />
          </div>
          <div className="md:col-span-2 space-y-2">
            <div className="flex justify-between items-center">
              <label className="text-sm font-semibold text-gray-700">About Me</label>
              <button 
                onClick={handlePolishBio}
                disabled={isPolishing || !data.about}
                className="text-xs font-medium text-indigo-600 hover:text-indigo-700 flex items-center gap-1 disabled:opacity-50"
              >
                {isPolishing ? <Loader2 className="animate-spin" size={12} /> : <Sparkles size={12} />}
                Polish with AI
              </button>
            </div>
            <textarea 
              rows={4}
              value={data.about}
              onChange={(e) => updateField('about', e.target.value)}
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all resize-none"
              placeholder="Tell your story..."
            />
          </div>
        </div>
      </section>

      {/* Skills */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
          <span className="w-8 h-8 bg-indigo-100 text-indigo-600 rounded-lg flex items-center justify-center text-sm">2</span>
          Skills & Expertise
        </h2>
        <div className="flex flex-wrap gap-3 mb-6">
          {data.skills.map((skill, idx) => (
            <div key={idx} className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 text-indigo-700 rounded-full text-sm font-medium border border-indigo-100">
              {skill.name} ({skill.level}%)
              <button onClick={() => removeSkill(idx)} className="hover:text-red-500"><Trash2 size={14} /></button>
            </div>
          ))}
        </div>
        <div className="flex gap-4">
          <input 
            type="text" 
            value={newSkill.name}
            onChange={(e) => setNewSkill({ ...newSkill, name: e.target.value })}
            className="flex-1 px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none"
            placeholder="e.g. React.js"
          />
          <button 
            onClick={addSkill}
            className="bg-indigo-600 text-white px-6 py-3 rounded-xl font-semibold hover:bg-indigo-700 transition-colors flex items-center gap-2"
          >
            <Plus size={18} /> Add
          </button>
        </div>
      </section>

      {/* Projects */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold flex items-center gap-2">
            <span className="w-8 h-8 bg-indigo-100 text-indigo-600 rounded-lg flex items-center justify-center text-sm">3</span>
            Projects & Works
          </h2>
          <button 
            onClick={addProject}
            className="text-indigo-600 font-semibold flex items-center gap-2 hover:bg-indigo-50 px-4 py-2 rounded-xl transition-all"
          >
            <Plus size={18} /> Add Project
          </button>
        </div>

        <div className="grid grid-cols-1 gap-8">
          {data.projects.map((project) => (
            <div key={project.id} className="group relative bg-gray-50 p-6 rounded-2xl border border-gray-200 hover:border-indigo-300 transition-all">
              <button 
                onClick={() => removeProject(project.id)}
                className="absolute top-4 right-4 text-gray-400 hover:text-red-500 transition-colors"
              >
                <Trash2 size={20} />
              </button>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="md:col-span-1">
                  <img 
                    src={project.imageUrl} 
                    alt={project.title} 
                    className="w-full aspect-video rounded-xl object-cover shadow-sm mb-2" 
                  />
                  <input 
                    type="text"
                    value={project.imageUrl}
                    onChange={(e) => updateProject(project.id, { imageUrl: e.target.value })}
                    className="w-full text-xs text-gray-400 bg-transparent border-none outline-none focus:ring-0 truncate"
                    placeholder="Image URL..."
                  />
                </div>
                <div className="md:col-span-2 space-y-4">
                  <input 
                    type="text"
                    value={project.title}
                    onChange={(e) => updateProject(project.id, { title: e.target.value })}
                    className="text-xl font-bold bg-transparent w-full border-b border-gray-200 pb-1 focus:border-indigo-500 outline-none"
                    placeholder="Project Title"
                  />
                  <textarea 
                    rows={2}
                    value={project.description}
                    onChange={(e) => updateProject(project.id, { description: e.target.value })}
                    className="w-full bg-transparent text-gray-600 border-none outline-none focus:ring-0 resize-none"
                    placeholder="Brief description of your role and the outcome..."
                  />
                  <div className="flex gap-2">
                    <input 
                      type="text"
                      placeholder="Add tag (comma separated)"
                      onChange={(e) => {
                        if (e.target.value.endsWith(',')) {
                          const tag = e.target.value.replace(',', '').trim();
                          if (tag) updateProject(project.id, { tags: [...project.tags, tag] });
                          e.target.value = '';
                        }
                      }}
                      className="text-sm px-3 py-1 rounded-lg border border-gray-200 outline-none focus:border-indigo-500"
                    />
                    <div className="flex gap-2">
                      {project.tags.map((t, idx) => (
                        <span key={idx} className="text-xs bg-white border border-gray-200 px-2 py-1 rounded-md text-gray-500">
                          {t}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Socials */}
      <section className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-2xl font-bold mb-6 flex items-center gap-2">
          <span className="w-8 h-8 bg-indigo-100 text-indigo-600 rounded-lg flex items-center justify-center text-sm">4</span>
          Connect With You
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {['LinkedIn', 'Github', 'Instagram', 'Twitter'].map((platform) => (
            <div key={platform} className="space-y-1">
              <label className="text-xs font-semibold text-gray-500 uppercase tracking-wider">{platform}</label>
              <input 
                type="text" 
                value={(data.socials as any)[platform.toLowerCase()] || ''}
                onChange={(e) => updateSocial(platform.toLowerCase(), e.target.value)}
                className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 outline-none"
                placeholder={`${platform} profile link`}
              />
            </div>
          ))}
        </div>
      </section>

      <div className="flex justify-end pt-8">
        <button 
          onClick={onNext}
          className="bg-indigo-600 text-white px-10 py-4 rounded-2xl font-bold text-lg shadow-xl shadow-indigo-200 hover:bg-indigo-700 hover:shadow-2xl transition-all transform hover:-translate-y-1 flex items-center gap-3"
        >
          Preview Portfolio <ArrowRight size={20} />
        </button>
      </div>
    </div>
  );
};

export default EditorForm;

