import React, { useState, useEffect } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import ThemeSelector from './components/ThemeSelector';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  ChevronRight, 
  Monitor, 
  Eye, 
  Download,
  Share2,
  CheckCircle2,
  Copy,
  Check
} from 'lucide-react';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    view: 'landing',
    data: INITIAL_DATA,
    theme: 'minimal',
  });
  const [copied, setCopied] = useState(false);

  // Load data from URL if present
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const encodedData = params.get('p');
    if (encodedData) {
      try {
        const decoded = JSON.parse(atob(encodedData));
        setState(prev => ({
          ...prev,
          data: decoded.data || prev.data,
          theme: decoded.theme || prev.theme,
          view: 'preview'
        }));
      } catch (e) {
        console.error("Failed to decode portfolio data from URL", e);
      }
    }
  }, []);

  const setCategory = (category: Category) => {
    setState(prev => ({
      ...prev,
      data: { ...prev.data, category },
      view: 'editor'
    }));
  };

  const updateData = (data: PortfolioData) => {
    setState(prev => ({ ...prev, data }));
  };

  const setTheme = (theme: Theme) => {
    setState(prev => ({ ...prev, theme }));
  };

  const goToPreview = () => {
    setState(prev => ({ ...prev, view: 'preview' }));
    window.scrollTo(0, 0);
  };

  const backToEditor = () => {
    setState(prev => ({ ...prev, view: 'editor' }));
  };

  const backToLanding = () => {
    setState(prev => ({ ...prev, view: 'landing' }));
  };

  const handleShare = () => {
    const payload = btoa(JSON.stringify({ data: state.data, theme: state.theme }));
    const shareUrl = `${window.location.origin}${window.location.pathname}?p=${payload}`;
    navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    alert("Shareable portfolio link copied to clipboard!");
  };

  const handleDownload = () => {
    // Generate a standalone HTML string
    // We can't easily "renderToString" without a heavy library here, 
    // so we'll provide instructions or a simplified export.
    // For a real app, this would use a static template.
    const htmlContent = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${state.data.fullName} - Portfolio</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Playfair+Display:ital,wght@0,400..900;1,400..900&display=swap" rel="stylesheet">
    <style>
        body { font-family: 'Inter', sans-serif; }
        .font-serif { font-family: 'Playfair Display', serif; }
    </style>
</head>
<body>
    <div id="content">
        <!-- STANDALONE PORTFOLIO EXPORT -->
        <div style="padding: 50px; text-align: center; font-family: sans-serif;">
            <h1>${state.data.fullName}</h1>
            <p>${state.data.tagline}</p>
            <hr/>
            <p>This is a portable export of your portfolio data.</p>
            <p>Email: ${state.data.email}</p>
            <p>About: ${state.data.about}</p>
            <section>
               <h2>Projects</h2>
               ${state.data.projects.map(p => `
                 <div style="margin-bottom: 20px; border: 1px solid #ddd; padding: 10px;">
                   <h3>${p.title}</h3>
                   <p>${p.description}</p>
                   <a href="${p.link}">View Project</a>
                 </div>
               `).join('')}
            </section>
        </div>
    </div>
    <script>
       console.log("Portfolio data:", ${JSON.stringify(state.data)});
    </script>
</body>
</html>`;

    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${state.data.fullName.replace(/\s+/g, '_')}_Portfolio.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Navigation Header */}
      {state.view !== 'preview' && (
        <header className="bg-white border-b border-gray-100 sticky top-0 z-50">
          <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
            <div className="flex items-center gap-3 cursor-pointer" onClick={backToLanding}>
              <div className="w-10 h-10 bg-indigo-600 text-white rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200">
                <Rocket size={20} />
              </div>
              <h1 className="text-xl font-bold tracking-tight hidden sm:block">FreelancePortfolio</h1>
            </div>

            <div className="flex items-center gap-6">
              {state.view === 'editor' && (
                <div className="hidden md:flex items-center gap-2 text-sm text-gray-400">
                  <span className="text-indigo-600 font-semibold flex items-center gap-1">
                    <CheckCircle2 size={16} /> Category
                  </span>
                  <ChevronRight size={14} />
                  <span className="text-indigo-600 font-semibold">Details</span>
                  <ChevronRight size={14} />
                  <span>Review</span>
                </div>
              )}
              <button 
                onClick={state.view === 'editor' ? goToPreview : () => {}}
                className={`flex items-center gap-2 px-5 py-2.5 rounded-full font-bold text-sm transition-all
                  ${state.view === 'landing' ? 'hidden' : 'bg-indigo-600 text-white shadow-lg hover:shadow-indigo-200'}
                `}
              >
                <Eye size={18} /> Preview
              </button>
            </div>
          </div>
        </header>
      )}

      {/* Main Content Area */}
      <main className={state.view === 'preview' ? '' : 'max-w-7xl mx-auto px-4 py-12'}>

        {state.view === 'landing' && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="text-center max-w-3xl mx-auto mb-16">
              <span className="inline-block px-4 py-1.5 bg-indigo-50 text-indigo-700 rounded-full text-sm font-bold tracking-wide uppercase mb-6">
                Portfolio Generator
              </span>
              <h2 className="text-5xl md:text-6xl font-black text-gray-900 mb-6 leading-tight">
                Your talent, beautifully showcased.
              </h2>
              <p className="text-xl text-gray-500 mb-10 leading-relaxed">
                Build a professional portfolio in minutes. Choose your domain, add your works, and let AI polish your brand voice.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {CATEGORIES.map((cat) => (
                <CategoryCard 
                  key={cat.id}
                  id={cat.id}
                  icon={cat.icon}
                  description={cat.description}
                  selected={state.data.category === cat.id}
                  onSelect={setCategory}
                />
