                        <PortfolioPreview data={state.data} theme={state.theme} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {state.view === 'preview' && (
            <div className="relative animate-in fade-in duration-1000">
              <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-white/90 backdrop-blur-2xl px-8 py-6 rounded-[3rem] shadow-[0_30px_100px_rgba(0,0,0,0.15)] border border-white w-[95%] max-w-3xl flex flex-col gap-6">
