                  </div>
                </div>
                <div className="pt-4 border-t border-gray-100">
                  <ThemeSelector current={state.theme} onChange={setTheme} />
                </div>
              </div>
              <div className="min-h-screen">
                <PortfolioPreview data={state.data} theme={state.theme} />
              </div>
              <div className="h-56 bg-transparent"></div>
