                >
                  {isAuthLoading ? <Loader2 className="animate-spin" size={18} /> : (isSignUp ? 'Sign Up Now' : 'Enter Workspace')}
                  {!isAuthLoading && <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />}
                </button>
              </form>

              <div className="mt-8 pt-8 border-t border-indigo-50 text-center">
                <p className="text-sm font-medium text-gray-500">
                  {isSignUp ? 'Already have an account?' : 'New here?'} 
                  <button 
                    onClick={() => setIsSignUp(!isSignUp)}
                    className="text-indigo-600 font-bold hover:underline ml-1"
                  >
                    {isSignUp ? 'Login instead' : 'Create an account'}
                  </button>
                </p>
              </div>
            </div>

            <div className="mt-10 flex items-center justify-center gap-6 text-gray-300">
               <div className="flex items-center gap-2">
                 <ShieldCheck size={16} />
                 <span className="text-[10px] font-bold uppercase tracking-widest">End-to-End Encryption</span>
               </div>
            </div>
          </div>
        </div>
      )}

      {state.view !== 'login' && state.view !== 'preview' && (
        <header className="bg-white/80 backdrop-blur-md border-b border-indigo-50 sticky top-0 z-[60]">
          <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
            <div className="flex items-center gap-3 cursor-pointer group" onClick={backToLanding}>
              <div className="w-11 h-11 bg-indigo-600 text-white rounded-[1rem] flex items-center justify-center shadow-lg shadow-indigo-200 group-hover:scale-110 group-hover:rotate-3 transition-all duration-300">
                <Rocket size={24} />
              </div>
              <div>
                <h1 className="text-xl font-black tracking-tighter text-gray-900 leading-none">FreelancePortfolio</h1>
                <span className="text-[10px] uppercase tracking-widest font-bold text-indigo-500">Creator Hub</span>
