                  <div className="bg-white/70 backdrop-blur-md p-8 rounded-[2.5rem] border border-white shadow-2xl shadow-indigo-100/30">
                    <div className="flex items-center justify-between mb-6">
                      <h4 className="font-black text-gray-900 uppercase tracking-tighter flex items-center gap-2"><Monitor size={20} className="text-indigo-600" /> Live View</h4>
                      <div className="flex items-center gap-2">
                         <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
                         <span className="text-[10px] font-bold text-green-600 uppercase">Live</span>
                      </div>
                    </div>
                    <div className="aspect-[3/4] rounded-2xl overflow-hidden border-4 border-gray-900 scale-100 origin-top shadow-2xl bg-gray-50 relative group">
                      <div className="scale-[0.38] origin-top-left w-[263%] h-[263%]">
                        <PortfolioPreview data={state.data} theme={state.theme} />
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {state.view === 'preview' && (
            <div className="relative animate-in fade-in duration-1000">
              <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-white/90 backdrop-blur-2xl px-8 py-6 rounded-[3rem] shadow-[0_30px_100px_rgba(0,0,0,0.15)] border border-white w-[95%] max-w-3xl flex flex-col gap-6">
                <div className="flex items-center justify-between w-full">
                  <div className="flex items-center gap-4">
                    <button onClick={backToEditor} className="w-12 h-12 flex items-center justify-center hover:bg-gray-100 rounded-2xl transition-all text-gray-500 active:scale-90"><ArrowLeft size={24} /></button>
                    <div className="hidden sm:block">
                      <h5 className="font-black uppercase tracking-tighter text-lg leading-none">Publish Center</h5>
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Review & Export</p>
                    </div>
                  </div>
                  <div className="flex gap-3">
                    <button onClick={handleDownload} className="flex items-center gap-2.5 px-6 py-3 bg-gray-100 text-gray-900 rounded-2xl text-sm font-black uppercase tracking-widest hover:bg-gray-200 transition-all active:scale-95"><Download size={18} /> HTML</button>
                    <button onClick={handleShare} className="flex items-center gap-2.5 px-8 py-3 bg-indigo-600 text-white rounded-2xl text-sm font-black uppercase tracking-widest shadow-xl shadow-indigo-200 hover:bg-indigo-700 transition-all active:scale-95">
                      {copied ? <Check size={18} /> : <Share2 size={18} />} {copied ? 'Link Saved' : 'Share Now'}
                    </button>
                  </div>
                </div>
                <div className="pt-4 border-t border-gray-100">
                  <ThemeSelector current={state.theme} onChange={setTheme} />
                </div>
              </div>
              <div className="min-h-screen">
                <PortfolioPreview data={state.data} theme={state.theme} />
              </div>
              <div className="h-56 bg-transparent"></div>
            </div>
          )}
        </main>
      )}

      {state.view !== 'login' && state.view !== 'preview' && (
        <footer className="bg-white/80 backdrop-blur-md border-t border-indigo-50 py-24 px-6">
          <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-3 gap-16 items-center">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-2xl shadow-indigo-200"><Rocket size={24} /></div>
              <div>
                <h1 className="text-2xl font-black tracking-tighter leading-none">FreelancePortfolio</h1>
                <p className="text-[10px] uppercase font-bold text-indigo-500 tracking-widest mt-1">Design without limits</p>
              </div>
            </div>
            <div className="text-center md:text-right">
              <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">© {new Date().getFullYear()} FreelancePortfolio.</p>
              <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-indigo-400 mt-2">
                <ShieldCheck size={12} /> Powered by Supabase
              </div>
            </div>
          </div>
        </footer>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import ThemeSelector from './components/ThemeSelector';
import { supabase } from './services/supabase';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  ChevronRight, 
  Monitor, 
  Eye, 
  Download,
  Share2,
  CheckCircle2,
  Check,
  Zap,
  Lock,
  Mail,
  ArrowRight,
  ShieldCheck,
  Loader2,
  LogOut,
  CloudUpload,
  CloudCheck,
  AlertTriangle
} from 'lucide-react';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    view: 'login',
    data: INITIAL_DATA,
    theme: 'minimal',
  });
  const [copied, setCopied] = useState(false);
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [isSignUp, setIsSignUp] = useState(false);
  const [userId, setUserId] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  // Use a ref to track if we're currently loading initial data to prevent overwriting it with a blank sync
  const isInitialLoad = useRef(true);

  // Fetch User Portfolio
  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle(); // maybeSingle doesn't throw error on 0 rows

      if (error) {
        console.error("Supabase Fetch Error:", error);
        if (error.code === '42P01') {
          setErrorMessage("Table 'portfolios' not found. Please create it in Supabase.");
        } else {
          setErrorMessage(error.message);
        }
        setSyncStatus('error');
        setState(prev => ({ ...prev, view: 'landing' }));
      } else if (data) {
        setState(prev => ({
          ...prev,
          data: data.content || INITIAL_DATA,
          theme: data.theme || 'minimal',
          view: 'landing'
        }));
        setSyncStatus('synced');
      } else {
        // New user, no data yet
        setState(prev => ({ ...prev, view: 'landing' }));
        setSyncStatus('idle');
      }
    } catch (err) {
      console.error("Unexpected Fetch Error:", err);
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
    }
  };

  // Auth Listener
  useEffect(() => {
    const checkUser = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setUserId(session.user.id);
        fetchUserPortfolio(session.user.id);
      }
    };

    checkUser();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        setUserId(session.user.id);
        if (isInitialLoad.current) {
          fetchUserPortfolio(session.user.id);
        }
      } else {
        setUserId(null);
        isInitialLoad.current = true;
        setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // Debounced Sync Logic
  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'login') return;

    const timer = setTimeout(() => {
      const performSync = async () => {
        setSyncStatus('syncing');
        try {
          const { error } = await supabase.from('portfolios').upsert({
            user_id: userId,
            content: state.data,
            theme: state.theme,
            updated_at: new Date().toISOString(),
          }, { onConflict: 'user_id' });

          if (error) throw error;
          setSyncStatus('synced');
          setTimeout(() => setSyncStatus('idle'), 3000);
        } catch (err: any) {
          console.error("Sync error:", err);
          setSyncStatus('error');
          setErrorMessage(err.message || "Failed to sync to cloud.");
        }
      };

      performSync();
    }, 1500); // 1.5s debounce

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
        alert("Account created! Please verify your email to log in.");
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      setErrorMessage(err.message || "Authentication failed.");
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const setCategory = (category: Category) => {
    setState(prev => ({
      ...prev,
      data: { ...prev.data, category },
      view: 'editor'
    }));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const updateData = (data: PortfolioData) => {
    setState(prev => ({ ...prev, data }));
  };

  const setTheme = (theme: Theme) => {
    setState(prev => ({ ...prev, theme }));
  };

  const goToPreview = () => {
    setState(prev => ({ ...prev, view: 'preview' }));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const backToEditor = () => {
    setState(prev => ({ ...prev, view: 'editor' }));
  };

  const backToLanding = () => {
    setState(prev => ({ ...prev, view: 'landing' }));
  };

  const handleShare = () => {
    const payload = btoa(JSON.stringify({ data: state.data, theme: state.theme }));
    const shareUrl = `${window.location.origin}${window.location.pathname}?p=${payload}`;
    navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const htmlContent = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>${state.data.fullName} - Portfolio</title><script src="https://cdn.tailwindcss.com"></script><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;700;800&family=Playfair+Display:ital,wght@0,400..900;1,400..900&display=swap" rel="stylesheet"><style>body { font-family: 'Plus Jakarta Sans', sans-serif; } .font-serif { font-family: 'Playfair Display', serif; }</style></head><body class="bg-gray-50"><div style="max-width: 800px; margin: 80px auto; padding: 40px; background: white; border-radius: 24px; box-shadow: 0 4px 20px rgba(0,0,0,0.05);"><h1 style="font-size: 3rem; font-weight: 800; margin-bottom: 1rem;">${state.data.fullName}</h1><p style="font-size: 1.25rem; color: #6366f1; font-weight: 600;">${state.data.tagline}</p><div style="margin: 32px 0; padding: 24px; background: #f8fafc; border-radius: 16px;"><p style="line-height: 1.6; color: #475569;">${state.data.about}</p></div><div style="display: flex; gap: 20px; margin-bottom: 40px;"><span style="font-size: 0.875rem; color: #94a3b8;">Email: ${state.data.email}</span><span style="font-size: 0.875rem; color: #94a3b8;">Location: ${state.data.location}</span></div>${state.data.qualifications?.length > 0 ? `<h2 style="font-size: 1.5rem; font-weight: 700; margin-bottom: 16px;">Education</h2><div style="margin-bottom: 32px;">${state.data.qualifications.map(q => `<div style="margin-bottom: 12px;"><strong>${q.degree}</strong> - ${q.institution} (${q.year})</div>`).join('')}</div>` : ''}${state.data.certifications?.length > 0 ? `<h2 style="font-size: 1.5rem; font-weight: 700; margin-bottom: 16px;">Certifications</h2><div style="margin-bottom: 32px;">${state.data.certifications.map(c => `<div style="margin-bottom: 12px;"><strong>${c.name}</strong> - ${c.issuer} (${c.date})</div>`).join('')}</div>` : ''}<h2 style="font-size: 1.5rem; font-weight: 700; margin-bottom: 24px;">Featured Projects</h2><div style="display: grid; grid-template-columns: 1fr; gap: 24px;">${state.data.projects.map(p => `<div style="padding: 24px; border: 1px solid #e2e8f0; border-radius: 16px;"><h3 style="font-weight: 700; font-size: 1.125rem;">${p.title}</h3><p style="color: #64748b; margin: 8px 0;">${p.description}</p><a href="${p.link}" style="color: #4f46e5; text-decoration: none; font-weight: 600; font-size: 0.875rem;">View Live &rarr;</a></div>`).join('')}</div></div></body></html>`;
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${state.data.fullName.replace(/\s+/g, '_')}_Portfolio.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen">
      <div className="fixed inset-0 overflow-hidden pointer-events-none z-[-1]">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-400/10 rounded-full blur-[120px] animate-float"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-purple-400/10 rounded-full blur-[120px] animate-float" style={{ animationDelay: '-3s' }}></div>
      </div>

      {state.view === 'login' && (
        <div className="min-h-screen flex items-center justify-center p-6 animate-in fade-in zoom-in duration-700">
          <div className="max-w-md w-full">
            <div className="text-center mb-10">
              <div className="inline-flex items-center justify-center w-20 h-20 bg-indigo-600 text-white rounded-[2rem] shadow-2xl shadow-indigo-200 mb-6 animate-bounce">
                <Rocket size={40} />
              </div>
              <h1 className="text-4xl font-black tracking-tighter text-gray-900 mb-2">
                {isSignUp ? 'Create Account' : 'Welcome Back'}
              </h1>
              <p className="text-gray-500 font-medium italic">Elevate your freelance presence with us.</p>
            </div>

            <div className="bg-white/70 backdrop-blur-2xl p-8 md:p-10 rounded-[2.5rem] shadow-[0_30px_80px_rgba(79,70,229,0.15)] border border-white">
              {errorMessage && (
                <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-2xl flex items-start gap-3 text-xs font-bold uppercase leading-relaxed">
                  <AlertTriangle size={16} className="shrink-0" />
                  {errorMessage}
                </div>
              )}

              <form onSubmit={handleLoginSubmit} className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">Professional Email</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-gray-400 group-focus-within:text-indigo-600 transition-colors">
                      <Mail size={18} />
                    </div>
                    <input 
                      type="email" 
                      required
                      value={loginEmail}
                      onChange={(e) => setLoginEmail(e.target.value)}
                      className="w-full pl-12 pr-6 py-4 rounded-2xl border border-indigo-50 bg-white focus:ring-4 focus:ring-indigo-500/5 outline-none transition-all font-medium" 
                      placeholder="alex@studio.com"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <div className="flex justify-between items-center px-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Secure Password</label>
                    {!isSignUp && <a href="#" className="text-[10px] font-black text-indigo-500 uppercase tracking-widest hover:text-indigo-700">Forgot?</a>}
                  </div>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-gray-400 group-focus-within:text-indigo-600 transition-colors">
                      <Lock size={18} />
                    </div>
                    <input 
                      type="password" 
                      required
                      value={loginPass}
                      onChange={(e) => setLoginPass(e.target.value)}
                      className="w-full pl-12 pr-6 py-4 rounded-2xl border border-indigo-50 bg-white focus:ring-4 focus:ring-indigo-500/5 outline-none transition-all font-medium" 
                      placeholder="••••••••"
                    />
                  </div>
                </div>

                <button 
                  type="submit"
                  disabled={isAuthLoading}
                  className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black uppercase tracking-widest text-sm shadow-xl shadow-indigo-200 hover:bg-indigo-700 hover:shadow-indigo-300 transition-all flex items-center justify-center gap-2 group disabled:opacity-70"
                >
                  {isAuthLoading ? <Loader2 className="animate-spin" size={18} /> : (isSignUp ? 'Sign Up Now' : 'Enter Workspace')}
                  {!isAuthLoading && <ArrowRight size={18} className="group-hover:translate-x-1 transition-transform" />}
                </button>
              </form>

              <div className="mt-8 pt-8 border-t border-indigo-50 text-center">
                <p className="text-sm font-medium text-gray-500">
                  {isSignUp ? 'Already have an account?' : 'New here?'} 
                  <button onClick={() => setIsSignUp(!isSignUp)} className="text-indigo-600 font-bold hover:underline ml-1">
                    {isSignUp ? 'Login instead' : 'Create an account'}
                  </button>
                </p>
              </div>
            </div>
          </div>
        </div>
      )}

      {state.view !== 'login' && state.view !== 'preview' && (
        <header className="bg-white/80 backdrop-blur-md border-b border-indigo-50 sticky top-0 z-[60]">
          <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
            <div className="flex items-center gap-3 cursor-pointer group" onClick={backToLanding}>
              <div className="w-11 h-11 bg-indigo-600 text-white rounded-[1rem] flex items-center justify-center shadow-lg shadow-indigo-200 group-hover:scale-110 group-hover:rotate-3 transition-all duration-300">
                <Rocket size={24} />
              </div>
              <div>
                <h1 className="text-xl font-black tracking-tighter text-gray-900 leading-none">FreelancePortfolio</h1>
                <span className="text-[10px] uppercase tracking-widest font-bold text-indigo-500">Creator Hub</span>
              </div>
            </div>

            <div className="flex items-center gap-4">
              {syncStatus !== 'idle' && (
                <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                  syncStatus === 'syncing' ? 'bg-indigo-50 text-indigo-600' : 
                  syncStatus === 'synced' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'
                }`}>
                  {syncStatus === 'syncing' ? <Loader2 className="animate-spin" size={12} /> : 
                   syncStatus === 'synced' ? <CloudCheck size={12} /> : <AlertTriangle size={12} />}
                  {syncStatus}
                </div>
              )}

              {state.view === 'editor' && (
                <div className="hidden lg:flex items-center gap-4 text-[11px] font-bold uppercase tracking-widest">
                  <span className="text-indigo-600 flex items-center gap-1.5 bg-indigo-50 px-3 py-1.5 rounded-full">
                    <CheckCircle2 size={14} /> Category
                  </span>
                  <div className="w-4 h-[1px] bg-indigo-100"></div>
                  <span className="text-indigo-600 flex items-center gap-1.5 bg-indigo-50 px-3 py-1.5 rounded-full">
                    <Zap size={14} /> Details
                  </span>
                  <div className="w-4 h-[1px] bg-indigo-100"></div>
                  <span className="text-gray-300">Publish</span>
                </div>
              )}

              <button onClick={state.view === 'editor' ? goToPreview : () => {}} className={`flex items-center gap-2.5 px-6 py-3 rounded-2xl font-bold text-sm transition-all ${state.view === 'landing' ? 'hidden' : 'bg-gray-900 text-white shadow-xl hover:bg-black active:scale-95'}`}>
                <Eye size={18} /> Preview Portfolio
              </button>

              <button onClick={handleLogout} className="p-3 text-gray-400 hover:text-red-500 transition-colors" title="Log Out">
                <LogOut size={20} />
              </button>
            </div>
          </div>
        </header>
      )}

      {state.view !== 'login' && (
        <main className={state.view === 'preview' ? '' : 'max-w-7xl mx-auto px-6 py-16 lg:py-24'}>
          {errorMessage && (
            <div className="mb-12 p-6 bg-red-50 border border-red-100 text-red-600 rounded-[2rem] flex items-center justify-between gap-6 max-w-4xl mx-auto animate-pulse">
               <div className="flex items-center gap-4">
                 <AlertTriangle size={24} />
                 <p className="text-sm font-black uppercase tracking-widest">{errorMessage}</p>
               </div>
               <button onClick={() => setErrorMessage(null)} className="text-[10px] font-black uppercase opacity-40 hover:opacity-100 underline tracking-widest">Dismiss</button>
            </div>
          )}

          {state.view === 'landing' && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000">
              <div className="text-center max-w-4xl mx-auto mb-20 relative">
                <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-indigo-600/5 text-indigo-600 rounded-full text-xs font-black tracking-widest uppercase mb-8 border border-indigo-600/10">
                  <Sparkles size={14} /> The Ultimate Portfolio Builder
                </div>
                <h2 className="text-6xl md:text-8xl font-black text-gray-900 mb-8 tracking-tighter leading-[0.95] md:leading-[0.9]">
                  Showcase your <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-purple-600">genius.</span>
                </h2>
                <p className="text-xl text-gray-500 mb-12 leading-relaxed max-w-2xl mx-auto font-medium">
                  Select a domain to start building your cloud-synced portfolio. Every update is saved to your Supabase backend automatically.
                </p>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                {CATEGORIES.map((cat) => (
                  <CategoryCard key={cat.id} id={cat.id} icon={cat.icon} description={cat.description} selected={state.data.category === cat.id} onSelect={setCategory} />
                ))}
