                      </div>
                      <div className="aspect-[3/4] rounded-2xl overflow-hidden border-4 border-gray-900 bg-gray-50 relative">
                        <div className="scale-[0.38] origin-top-left w-[263%] h-[263%]">
                          <PortfolioPreview data={state.data} theme={state.theme} />
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {state.view === 'preview' && (
              <div className="relative animate-in fade-in duration-1000">
                <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-white/90 backdrop-blur-2xl px-8 py-6 rounded-[3rem] shadow-2xl border border-white w-[95%] max-w-3xl flex flex-col gap-6">
                  <div className="flex items-center justify-between w-full">
                    <div className="flex items-center gap-4">
                      {userId && (
                        <button onClick={backToEditor} className="w-12 h-12 flex items-center justify-center hover:bg-gray-100 rounded-2xl text-gray-500"><ArrowLeft size={24} /></button>
                      )}
                      <div>
                        <h5 className="font-black uppercase tracking-tighter text-lg leading-none">Publish Center</h5>
                        <p className="text-[10px] font-bold text-gray-400 uppercase">Review & Export</p>
