                      <button onClick={handleShare} className="flex items-center gap-2.5 px-8 py-3 bg-indigo-600 text-white rounded-2xl text-sm font-black uppercase tracking-widest shadow-xl hover:bg-indigo-700 transition-all">
                        {copied ? <Check size={18} /> : <Share2 size={18} />} {copied ? 'Copied' : 'Share'}
                      </button>
                    </div>
