                <div className="h-56"></div>
              </div>
            )}
          </main>

          {state.view !== 'preview' && (
            <footer className="bg-white/80 backdrop-blur-md border-t border-indigo-50 py-16 px-6 text-center">
              <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-8">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-indigo-600 text-white rounded-xl flex items-center justify-center"><Rocket size={20} /></div>
                  <h1 className="text-xl font-black tracking-tighter">FreelancePortfolio</h1>
                </div>
