                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Final Polish</p>
                      </div>
                    </div>
                    <div className="flex gap-3">
                      <button onClick={() => {}} className="flex items-center gap-2.5 px-8 py-3 bg-indigo-600 text-white rounded-2xl text-sm font-black uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95">
                         Live View
                      </button>
                    </div>
                  </div>
                  <div className="pt-4 border-t border-gray-100">
                    <ThemeSelector current={state.theme} onChange={setTheme} />
                  </div>
                </div>
                <div className="min-h-screen">
                  <PortfolioPreview data={state.data} theme={state.theme} />
                </div>
                <div className="h-56"></div>
              </div>
            )}
          </main>

          {state.view !== 'preview' && (
            <footer className="bg-white border-t border-gray-100 py-24 px-6 text-center">
              <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-12">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-100"><Rocket size={24} /></div>
                  <div className="text-left">
                    <h1 className="text-2xl font-black tracking-tighter leading-none">FreelancePortal</h1>
                    <p className="text-[10px] uppercase font-bold text-indigo-500 tracking-widest mt-1 italic">Building your brand since 2025</p>
                  </div>
                </div>
                <div className="flex flex-col md:flex-row items-center gap-10">
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
                    <ShieldCheck size={14} className="text-green-500" /> AES-256 Encrypted Sync
                  </div>
                  <p className="text-xs font-bold text-gray-300 uppercase tracking-widest">© {new Date().getFullYear()} FreelancePortal.</p>
                </div>
              </div>
            </footer>
          )}
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import ThemeSelector from './components/ThemeSelector';
import { supabase } from './services/supabase';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  Monitor, 
  Eye, 
  Download,
  Share2,
  Check,
  Zap,
  Lock,
  Mail,
  ArrowRight,
  ShieldCheck,
  Loader2,
  LogOut,
  CloudUpload,
  CloudCheck,
  AlertTriangle,
  Database,
  Terminal,
  Copy,
  EyeOff,
  UserCheck,
  UserPlus,
  Info
} from 'lucide-react';

export default function App() {
  const [state, setState] = useState<AppState>({
    view: 'login',
    data: INITIAL_DATA,
    theme: 'minimal',
  });

  // Auth & Session State
  const [isInitializing, setIsInitializing] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);

  // UI State
  const [isSignUp, setIsSignUp] = useState(false);
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // App Sync State
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [showSqlFix, setShowSqlFix] = useState(false);
  const [copied, setCopied] = useState(false);

  const isInitialLoad = useRef(true);

  const SQL_FIX = `-- Run this in your Supabase SQL Editor:
CREATE TABLE IF NOT EXISTS portfolios (
  user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  content JSONB NOT NULL,
  theme TEXT NOT NULL DEFAULT 'minimal',
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS
ALTER TABLE portfolios ENABLE ROW LEVEL SECURITY;

-- Policy: Users can see their own portfolio
CREATE POLICY "Users can view own portfolio" ON portfolios
  FOR SELECT USING (auth.uid() = user_id);

-- Policy: Users can insert their own portfolio
CREATE POLICY "Users can insert own portfolio" ON portfolios
  FOR INSERT WITH CHECK (auth.uid() = user_id);

-- Policy: Users can update their own portfolio
CREATE POLICY "Users can update own portfolio" ON portfolios
  FOR UPDATE USING (auth.uid() = user_id);`;

  // Fetch User Portfolio
  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle();

      if (error) {
        if (error.code === '42P01') {
          setErrorMessage("Table 'portfolios' does not exist in your database.");
          setShowSqlFix(true);
        } else {
          setErrorMessage(error.message);
        }
        setSyncStatus('error');
      } else if (data) {
        setState(prev => ({
          ...prev,
          data: data.content || INITIAL_DATA,
          theme: (data.theme as Theme) || 'minimal',
          view: 'landing'
        }));
        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 2000);
      } else {
        setState(prev => ({ ...prev, view: 'landing' }));
        setSyncStatus('idle');
      }
    } catch (err: any) {
      setErrorMessage("Could not connect to Supabase.");
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
      setIsInitializing(false);
    }
  };

  // Auth Lifecycle Management
  useEffect(() => {
    const checkSession = async () => {
      // Handle shared links first
      const params = new URLSearchParams(window.location.search);
      const shared = params.get('p');
      if (shared) {
        try {
          const decoded = JSON.parse(decodeURIComponent(escape(atob(shared))));
          if (decoded.data) {
            setState(prev => ({
              ...prev,
              data: decoded.data,
              theme: decoded.theme || 'minimal',
              view: 'preview'
            }));
            setIsInitializing(false);
            return;
          }
        } catch (e) {
          console.error("Link decode error", e);
        }
      }

      // Check existing session
      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        fetchUserPortfolio(session.user.id);
      } else {
        setIsInitializing(false);
      }
    };

    checkSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        if (event === 'SIGNED_IN' || isInitialLoad.current) {
          fetchUserPortfolio(session.user.id);
        }
      } else {
        setUserId(null);
        setUserEmail(null);
        isInitialLoad.current = true;
        const params = new URLSearchParams(window.location.search);
        if (!params.has('p')) {
          setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
        }
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // Sync Logic
  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'login' || state.view === 'preview') return;

    const timer = setTimeout(() => {
      const performSync = async () => {
        setSyncStatus('syncing');
        try {
          const { error } = await supabase.from('portfolios').upsert({
            user_id: userId,
            content: state.data,
            theme: state.theme,
            updated_at: new Date().toISOString(),
          }, { onConflict: 'user_id' });

          if (error) throw error;
          setSyncStatus('synced');
          setTimeout(() => setSyncStatus('idle'), 3000);
        } catch (err: any) {
          setSyncStatus('error');
          if (err.code === '42501') {
             setErrorMessage("Permission denied. Check RLS policies.");
             setShowSqlFix(true);
          } else {
             setErrorMessage(err.message || "Failed to sync to cloud.");
          }
        }
      };
      performSync();
    }, 1500);

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
        setSuccessMessage("Account created! Please verify your email.");
        setIsSignUp(false);
        setLoginPass('');
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      if (err.message?.includes('rate limit exceeded')) {
        setErrorMessage("Email rate limit exceeded. Supabase only allows 3 emails per hour on the free tier. To fix this: Go to Supabase Dashboard > Authentication > Providers > Email and disable 'Confirm Email' or setup a custom SMTP.");
      } else {
        setErrorMessage(err.message || "Authentication failed.");
      }
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const updateData = (data: PortfolioData) => setState(prev => ({ ...prev, data }));
  const setTheme = (theme: Theme) => setState(prev => ({ ...prev, theme }));
  const goToPreview = () => setState(prev => ({ ...prev, view: 'preview' }));
  const backToEditor = () => setState(prev => ({ ...prev, view: 'editor' }));
  const backToLanding = () => setState(prev => ({ ...prev, view: 'landing' }));

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center">
        <div className="w-16 h-16 bg-indigo-600 text-white rounded-2xl flex items-center justify-center animate-bounce shadow-2xl shadow-indigo-200">
          <Rocket size={32} />
        </div>
        <p className="mt-6 text-sm font-black uppercase tracking-[0.3em] text-indigo-500 animate-pulse">Initializing Portal</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen selection:bg-indigo-100 selection:text-indigo-900">
      {/* Dynamic Background */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none z-[-1]">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-400/5 rounded-full blur-[120px] animate-pulse"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-purple-400/5 rounded-full blur-[120px] animate-pulse" style={{ animationDelay: '2s' }}></div>
      </div>

      {state.view === 'login' ? (
        <div className="min-h-screen flex items-center justify-center p-6 bg-[#fafafa]">
          <div className="max-w-md w-full">
            <div className="text-center mb-10">
              <div className="inline-flex items-center justify-center w-20 h-20 bg-indigo-600 text-white rounded-[2rem] shadow-2xl shadow-indigo-200 mb-6 group cursor-pointer hover:rotate-12 transition-transform duration-500">
                <Rocket size={40} />
              </div>
              <h1 className="text-5xl font-black tracking-tighter text-gray-900 mb-3">FreelancePortal</h1>
              <p className="text-gray-400 font-medium text-lg">Your craft, professionally exhibited.</p>
            </div>

            <div className="bg-white/80 backdrop-blur-3xl p-10 rounded-[2.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.08)] border border-white relative overflow-hidden">
              {/* Form Tab Switcher */}
              <div className="flex gap-4 mb-10 p-1 bg-gray-50 rounded-2xl">
                <button 
                  onClick={() => setIsSignUp(false)}
                  className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${!isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  Sign In
                </button>
                <button 
                  onClick={() => setIsSignUp(true)}
                  className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  Join Us
                </button>
              </div>

              {errorMessage && (
                <div className={`mb-6 p-4 border rounded-2xl flex flex-col gap-2 text-[11px] font-bold uppercase leading-relaxed ${errorMessage.includes('rate limit') ? 'bg-amber-50 border-amber-100 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'}`}>
                  <div className="flex items-start gap-3">
                    <AlertTriangle size={16} className="shrink-0" />
                    <span>{errorMessage}</span>
                  </div>
                  {errorMessage.includes('rate limit') && (
                    <div className="mt-2 p-3 bg-white/50 rounded-xl border border-amber-200/50 flex items-start gap-2 text-[10px] normal-case font-medium">
                      <Info size={14} className="shrink-0 text-amber-500 mt-0.5" />
                      <p>Supabase Free Tier limits sign-up emails to 3 per hour. Wait 60 minutes or disable email confirmation in your Supabase Auth settings.</p>
                    </div>
                  )}
                </div>
              )}

              {successMessage && (
                <div className="mb-6 p-4 bg-green-50 border border-green-100 text-green-600 rounded-2xl flex items-start gap-3 text-[11px] font-bold uppercase leading-relaxed">
                  <UserCheck size={16} className="shrink-0" />
                  {successMessage}
                </div>
              )}

              <form onSubmit={handleAuth} className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">Work Email</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-gray-400 group-focus-within:text-indigo-600 transition-colors">
                      <Mail size={18} />
                    </div>
                    <input 
                      type="email" 
                      required
                      value={loginEmail}
                      onChange={(e) => setLoginEmail(e.target.value)}
                      className="w-full pl-12 pr-6 py-4 rounded-2xl border border-indigo-50 bg-white/50 focus:bg-white focus:ring-4 focus:ring-indigo-500/5 outline-none transition-all font-medium" 
                      placeholder="alex@studio.com"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">Secure Password</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-gray-400 group-focus-within:text-indigo-600 transition-colors">
                      <Lock size={18} />
                    </div>
                    <input 
                      type={showPass ? "text" : "password"} 
                      required
                      value={loginPass}
                      onChange={(e) => setLoginPass(e.target.value)}
                      className="w-full pl-12 pr-14 py-4 rounded-2xl border border-indigo-50 bg-white/50 focus:bg-white focus:ring-4 focus:ring-indigo-500/5 outline-none transition-all font-medium" 
                      placeholder="••••••••"
                    />
                    <button 
                      type="button"
                      onClick={() => setShowPass(!showPass)}
                      className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-300 hover:text-indigo-500 transition-colors"
                    >
                      {showPass ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>
                  </div>
                </div>

                <button 
                  type="submit"
                  disabled={isAuthLoading}
                  className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black uppercase tracking-widest text-sm shadow-xl shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-70 transition-all flex items-center justify-center gap-3 group"
                >
                  {isAuthLoading ? <Loader2 className="animate-spin" size={20} /> : (isSignUp ? <><UserPlus size={18} /> Register</> : <><ArrowRight size={18} /> Sign In</>)}
                </button>
              </form>
            </div>
          </div>
        </div>
      ) : (
        <>
          {state.view !== 'preview' && (
            <header className="bg-white/90 backdrop-blur-md border-b border-gray-100 sticky top-0 z-[60]">
              <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
                <div className="flex items-center gap-3 cursor-pointer group" onClick={backToLanding}>
                  <div className="w-11 h-11 bg-indigo-600 text-white rounded-[1rem] flex items-center justify-center shadow-lg shadow-indigo-100 group-hover:scale-110 group-hover:rotate-3 transition-all duration-300">
                    <Rocket size={24} />
                  </div>
                  <h1 className="text-xl font-black tracking-tighter text-gray-900 leading-none">FreelancePortfolio</h1>
                </div>

                <div className="flex items-center gap-6">
                  {syncStatus !== 'idle' && (
                    <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                      syncStatus === 'syncing' ? 'bg-indigo-50 text-indigo-600' : 
                      syncStatus === 'synced' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'
                    }`}>
                      {syncStatus === 'syncing' ? <Loader2 className="animate-spin" size={12} /> : 
                       syncStatus === 'synced' ? <CloudCheck size={12} /> : <AlertTriangle size={12} />}
                      {syncStatus}
                    </div>
                  )}

                  <div className="hidden md:flex flex-col items-end border-r border-gray-100 pr-6">
                    <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Authenticated As</span>
                    <span className="text-xs font-bold text-gray-900 truncate max-w-[150px]">{userEmail}</span>
                  </div>

                  <div className="flex items-center gap-2">
                    <button onClick={state.view === 'editor' ? goToPreview : () => {}} className={`flex items-center gap-2.5 px-6 py-3 rounded-2xl font-bold text-sm transition-all ${state.view === 'landing' ? 'hidden' : 'bg-gray-900 text-white shadow-xl hover:bg-black'}`}>
                      <Eye size={18} /> Preview
                    </button>

                    <button onClick={handleLogout} className="w-12 h-12 flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all" title="Sign Out">
                      <LogOut size={20} />
                    </button>
                  </div>
                </div>
              </div>
            </header>
          )}

          <main className={state.view === 'preview' ? '' : 'max-w-7xl mx-auto px-6 py-16 lg:py-24'}>
            {state.view === 'landing' && (
              <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000">
                <div className="text-center max-w-4xl mx-auto mb-20 relative">
                  <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black tracking-widest uppercase mb-8 border border-indigo-100">
                    <Sparkles size={14} /> Design Your Future
                  </div>
                  <h2 className="text-6xl md:text-8xl font-black text-gray-900 mb-8 tracking-tighter leading-[0.95] md:leading-[0.9]">
                    Showcase your <br/><span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-purple-600">creative soul.</span>
                  </h2>
                  <p className="text-xl text-gray-400 font-medium max-w-2xl mx-auto leading-relaxed">Choose a category to start your professional legacy.</p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                  {CATEGORIES.map((cat) => (
                    <CategoryCard 
                      key={cat.id} 
                      id={cat.id} 
                      icon={cat.icon} 
                      description={cat.description} 
                      selected={state.data.category === cat.id} 
                      onSelect={(id) => {
                        setState(prev => ({ ...prev, data: { ...prev.data, category: id }, view: 'editor' }));
                        window.scrollTo(0,0);
                      }} 
                    />
                  ))}
                </div>
              </div>
            )}

            {state.view === 'editor' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                <div className="lg:col-span-8 animate-in fade-in slide-in-from-left-8 duration-700">
                  <button onClick={backToLanding} className="group inline-flex items-center gap-3 text-sm font-bold text-gray-400 hover:text-indigo-600 mb-10 transition-colors">
                    <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> 
                    <span className="uppercase tracking-widest text-[10px] font-black">Change Domain</span>
                  </button>
                  <EditorForm data={state.data} onChange={updateData} onNext={goToPreview} />
                </div>

                <div className="lg:col-span-4 hidden lg:block">
                  <div className="sticky top-32">
                    <div className="bg-white/70 backdrop-blur-md p-8 rounded-[2.5rem] border border-white shadow-2xl">
                      <div className="flex items-center justify-between mb-6">
                        <h4 className="font-black text-gray-900 uppercase tracking-tighter flex items-center gap-2 italic">
                          <Monitor size={20} className="text-indigo-600" /> Preview Canvas
                        </h4>
                      </div>
                      <div className="aspect-[3/4] rounded-2xl overflow-hidden border-4 border-gray-900 bg-gray-50 relative shadow-2xl">
                        <div className="scale-[0.38] origin-top-left w-[263%] h-[263%]">
                          <PortfolioPreview data={state.data} theme={state.theme} />
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {state.view === 'preview' && (
              <div className="relative animate-in fade-in duration-1000">
                <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-white/90 backdrop-blur-2xl px-8 py-6 rounded-[3rem] shadow-[0_30px_80px_rgba(0,0,0,0.15)] border border-white w-[95%] max-w-3xl flex flex-col gap-6">
                  <div className="flex items-center justify-between w-full">
                    <div className="flex items-center gap-4">
                      {userId && (
                        <button onClick={backToEditor} className="w-12 h-12 flex items-center justify-center hover:bg-gray-100 rounded-2xl text-gray-500 transition-colors"><ArrowLeft size={24} /></button>
                      )}
                      <div>
                        <h5 className="font-black uppercase tracking-tighter text-lg leading-none">Studio Editor</h5>
                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Final Polish</p>
                      </div>
                    </div>
                    <div className="flex gap-3">
                      <button onClick={() => {}} className="flex items-center gap-2.5 px-8 py-3 bg-indigo-600 text-white rounded-2xl text-sm font-black uppercase tracking-widest shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95">
                         Live View
                      </button>
                    </div>
                  </div>
                  <div className="pt-4 border-t border-gray-100">
                    <ThemeSelector current={state.theme} onChange={setTheme} />
                  </div>
                </div>
                <div className="min-h-screen">
                  <PortfolioPreview data={state.data} theme={state.theme} />
                </div>
                <div className="h-56"></div>
              </div>
            )}
          </main>

          {state.view !== 'preview' && (
            <footer className="bg-white border-t border-gray-100 py-24 px-6 text-center">
              <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-12">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-100"><Rocket size={24} /></div>
                  <div className="text-left">
                    <h1 className="text-2xl font-black tracking-tighter leading-none">FreelancePortfolio</h1>
                    <p className="text-[10px] uppercase font-bold text-indigo-500 tracking-widest mt-1 italic">Building your brand since 2025</p>
                  </div>
                </div>
                <div className="flex flex-col md:flex-row items-center gap-10">
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">
                    <ShieldCheck size={14} className="text-green-500" /> AES-256 Encrypted Sync
                  </div>
                  <p className="text-xs font-bold text-gray-300 uppercase tracking-widest">© {new Date().getFullYear()} FreelancePortfolio.</p>
                </div>
              </div>
            </footer>
          )}
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import ThemeSelector from './components/ThemeSelector';
import { supabase } from './services/supabase';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  Monitor, 
  Eye, 
  Download,
  Share2,
  Check,
  Zap,
  Lock,
  Mail,
  ArrowRight,
  ShieldCheck,
  Loader2,
  LogOut,
  CloudUpload,
  CloudCheck,
  AlertTriangle,
  Database,
  Terminal,
  Copy,
  EyeOff,
  UserCheck,
  UserPlus,
  Info,
  Globe,
  ExternalLink
} from 'lucide-react';

export default function App() {
  const [state, setState] = useState<AppState>({
    view: 'login',
    data: INITIAL_DATA,
    theme: 'minimal',
  });

  // Auth & Session State
  const [isInitializing, setIsInitializing] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);

  // UI State
  const [isSignUp, setIsSignUp] = useState(false);
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // App Sync State
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [isPublishing, setIsPublishing] = useState(false);
  const [hasPublished, setHasPublished] = useState(false);
  const [copied, setCopied] = useState(false);

  const isInitialLoad = useRef(true);

  // Fetch User Portfolio
  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle();

      if (error) {
        setErrorMessage(error.message);
        setSyncStatus('error');
      } else if (data) {
        setState(prev => ({
          ...prev,
          data: data.content || INITIAL_DATA,
          theme: (data.theme as Theme) || 'minimal',
          view: 'landing'
        }));
        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 2000);
      } else {
        setState(prev => ({ ...prev, view: 'landing' }));
        setSyncStatus('idle');
      }
    } catch (err: any) {
      setErrorMessage("Could not connect to Supabase.");
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
      setIsInitializing(false);
    }
  };

  // Auth Lifecycle Management
  useEffect(() => {
    const checkSession = async () => {
      const params = new URLSearchParams(window.location.search);
      const shared = params.get('p');
      if (shared) {
        try {
          const decoded = JSON.parse(decodeURIComponent(escape(atob(shared))));
          if (decoded.data) {
            setState(prev => ({
              ...prev,
              data: decoded.data,
              theme: decoded.theme || 'minimal',
              view: 'preview'
            }));
            setIsInitializing(false);
            return;
          }
        } catch (e) {
          console.error("Link decode error", e);
        }
      }

      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        fetchUserPortfolio(session.user.id);
      } else {
        setIsInitializing(false);
      }
    };

    checkSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        if (event === 'SIGNED_IN' || isInitialLoad.current) {
          fetchUserPortfolio(session.user.id);
        }
      } else {
        setUserId(null);
        setUserEmail(null);
        isInitialLoad.current = true;
        const params = new URLSearchParams(window.location.search);
        if (!params.has('p')) {
          setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
        }
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // Auto Sync Logic
  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'login' || state.view === 'preview') return;

    const timer = setTimeout(() => {
      performSync();
    }, 1500);

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const performSync = async () => {
    if (!userId) return;
    setSyncStatus('syncing');
    try {
      const { error } = await supabase.from('portfolios').upsert({
        user_id: userId,
        content: state.data,
        theme: state.theme,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id' });

      if (error) throw error;
      setSyncStatus('synced');
      setTimeout(() => setSyncStatus('idle'), 3000);
      return true;
    } catch (err: any) {
      setSyncStatus('error');
      setErrorMessage(err.message || "Failed to sync to cloud.");
      return false;
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
        setSuccessMessage("Account created! Please verify your email.");
        setIsSignUp(false);
        setLoginPass('');
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      if (err.message?.includes('rate limit exceeded')) {
        setErrorMessage("Email rate limit exceeded. Supabase only allows 3 emails per hour on the free tier.");
      } else {
        setErrorMessage(err.message || "Authentication failed.");
      }
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  // Export Logic
  const handleDownload = () => {
    const { fullName, tagline, about, email, location, skills, projects } = state.data;
    const htmlContent = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${fullName} | Portfolio</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;800&display=swap" rel="stylesheet">
    <style>
        body { font-family: 'Plus Jakarta Sans', sans-serif; }
    </style>
</head>
<body class="bg-slate-50 text-slate-900">
    <header class="py-24 px-6 text-center bg-white border-b border-slate-100">
        <h1 class="text-6xl font-black tracking-tighter mb-4">${fullName}</h1>
        <p class="text-xl text-slate-500 max-w-2xl mx-auto">${tagline}</p>
        <div class="mt-8 flex justify-center gap-6 text-slate-400 font-bold uppercase tracking-widest text-xs">
            <span>${email}</span>
            <span>•</span>
            <span>${location}</span>
        </div>
    </header>
    <main class="max-w-5xl mx-auto py-20 px-6">
        <section class="mb-24">
            <h2 class="text-xs font-black uppercase tracking-[0.3em] text-indigo-600 mb-8">About Me</h2>
            <p class="text-2xl leading-relaxed text-slate-700 whitespace-pre-wrap">${about}</p>
        </section>

        <section class="mb-24">
            <h2 class="text-xs font-black uppercase tracking-[0.3em] text-indigo-600 mb-10">Core Skills</h2>
            <div class="flex flex-wrap gap-3">
                ${skills.map(s => `<span class="px-5 py-3 bg-white border border-slate-200 rounded-2xl text-sm font-bold shadow-sm">${s.name} (${s.level}%)</span>`).join('')}
            </div>
        </section>

        <section>
            <h2 class="text-xs font-black uppercase tracking-[0.3em] text-indigo-600 mb-12">Featured Projects</h2>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-8">
                ${projects.map(p => `
                    <div class="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all">
                        <h3 class="text-2xl font-black mb-3">${p.title}</h3>
                        <p class="text-slate-500 mb-6 leading-relaxed">${p.description}</p>
                        ${p.link ? `<a href="${p.link}" target="_blank" class="inline-flex items-center gap-2 text-indigo-600 font-bold uppercase tracking-widest text-[10px]">View Work &rarr;</a>` : ''}
                    </div>
                `).join('')}
            </div>
        </section>
    </main>
    <footer class="py-20 text-center border-t border-slate-100 opacity-40 text-xs font-bold uppercase tracking-widest">
        © ${new Date().getFullYear()} ${fullName}. Built with FreelancePortfolio.
    </footer>
</body>
</html>`;

    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fullName.replace(/\s+/g, '_')}_Portfolio.html`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleShare = () => {
    const payload = btoa(unescape(encodeURIComponent(JSON.stringify({ data: state.data, theme: state.theme }))));
    const url = `${window.location.origin}${window.location.pathname}?p=${payload}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    const success = await performSync();
    if (success) {
      setHasPublished(true);
    }
    setIsPublishing(false);
  };

  const updateData = (data: PortfolioData) => setState(prev => ({ ...prev, data }));
  const setTheme = (theme: Theme) => setState(prev => ({ ...prev, theme }));
  const goToPreview = () => setState(prev => ({ ...prev, view: 'preview' }));
  const backToEditor = () => setState(prev => ({ ...prev, view: 'editor' }));
  const backToLanding = () => setState(prev => ({ ...prev, view: 'landing' }));

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center">
        <div className="w-16 h-16 bg-indigo-600 text-white rounded-2xl flex items-center justify-center animate-bounce shadow-2xl shadow-indigo-200">
          <Rocket size={32} />
        </div>
        <p className="mt-6 text-sm font-black uppercase tracking-[0.3em] text-indigo-500 animate-pulse">Initializing Portal</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen selection:bg-indigo-100 selection:text-indigo-900">
      <div className="fixed inset-0 overflow-hidden pointer-events-none z-[-1]">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-400/5 rounded-full blur-[120px] animate-pulse"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-purple-400/5 rounded-full blur-[120px] animate-pulse" style={{ animationDelay: '2s' }}></div>
      </div>

      {state.view === 'login' ? (
        <div className="min-h-screen flex items-center justify-center p-6 bg-[#fafafa]">
          <div className="max-w-md w-full">
            <div className="text-center mb-10">
              <div className="inline-flex items-center justify-center w-20 h-20 bg-indigo-600 text-white rounded-[2rem] shadow-2xl shadow-indigo-200 mb-6 group cursor-pointer hover:rotate-12 transition-transform duration-500">
                <Rocket size={40} />
              </div>
              <h1 className="text-5xl font-black tracking-tighter text-gray-900 mb-3">FreelancePortal</h1>
              <p className="text-gray-400 font-medium text-lg">Your craft, professionally exhibited.</p>
            </div>

            <div className="bg-white/80 backdrop-blur-3xl p-10 rounded-[2.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.08)] border border-white relative overflow-hidden">
              <div className="flex gap-4 mb-10 p-1 bg-gray-50 rounded-2xl">
                <button 
                  onClick={() => setIsSignUp(false)}
                  className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${!isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  Sign In
                </button>
                <button 
                  onClick={() => setIsSignUp(true)}
                  className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  Join Us
                </button>
              </div>

              {errorMessage && (
                <div className={`mb-6 p-4 border rounded-2xl flex flex-col gap-2 text-[11px] font-bold uppercase leading-relaxed ${errorMessage.includes('rate limit') ? 'bg-amber-50 border-amber-100 text-amber-700' : 'bg-red-50 border-red-100 text-red-600'}`}>
                  <div className="flex items-start gap-3">
                    <AlertTriangle size={16} className="shrink-0" />
                    <span>{errorMessage}</span>
                  </div>
                </div>
              )}

              {successMessage && (
                <div className="mb-6 p-4 bg-green-50 border border-green-100 text-green-600 rounded-2xl flex items-start gap-3 text-[11px] font-bold uppercase leading-relaxed">
                  <UserCheck size={16} className="shrink-0" />
                  {successMessage}
                </div>
              )}

              <form onSubmit={handleAuth} className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">Work Email</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-gray-400 group-focus-within:text-indigo-600 transition-colors">
                      <Mail size={18} />
                    </div>
                    <input 
                      type="email" 
                      required
                      value={loginEmail}
                      onChange={(e) => setLoginEmail(e.target.value)}
                      className="w-full pl-12 pr-6 py-4 rounded-2xl border border-indigo-50 bg-white/50 focus:bg-white focus:ring-4 focus:ring-indigo-500/5 outline-none transition-all font-medium" 
                      placeholder="alex@studio.com"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-2">Secure Password</label>
                  <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none text-gray-400 group-focus-within:text-indigo-600 transition-colors">
                      <Lock size={18} />
                    </div>
                    <input 
                      type={showPass ? "text" : "password"} 
                      required
                      value={loginPass}
                      onChange={(e) => setLoginPass(e.target.value)}
                      className="w-full pl-12 pr-14 py-4 rounded-2xl border border-indigo-50 bg-white/50 focus:bg-white focus:ring-4 focus:ring-indigo-500/5 outline-none transition-all font-medium" 
                      placeholder="••••••••"
                    />
                    <button 
                      type="button"
                      onClick={() => setShowPass(!showPass)}
                      className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-300 hover:text-indigo-500 transition-colors"
                    >
                      {showPass ? <EyeOff size={18} /> : <Eye size={18} />}
                    </button>
                  </div>
                </div>

                <button 
                  type="submit"
                  disabled={isAuthLoading}
                  className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black uppercase tracking-widest text-sm shadow-xl shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-70 transition-all flex items-center justify-center gap-3 group"
                >
                  {isAuthLoading ? <Loader2 className="animate-spin" size={20} /> : (isSignUp ? <><UserPlus size={18} /> Register</> : <><ArrowRight size={18} /> Sign In</>)}
                </button>
              </form>
            </div>
          </div>
        </div>
      ) : (
        <>
          {state.view !== 'preview' && (
            <header className="bg-white/90 backdrop-blur-md border-b border-gray-100 sticky top-0 z-[60]">
              <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
                <div className="flex items-center gap-3 cursor-pointer group" onClick={backToLanding}>
                  <div className="w-11 h-11 bg-indigo-600 text-white rounded-[1rem] flex items-center justify-center shadow-lg shadow-indigo-100 group-hover:scale-110 group-hover:rotate-3 transition-all duration-300">
                    <Rocket size={24} />
                  </div>
                  <h1 className="text-xl font-black tracking-tighter text-gray-900 leading-none">FreelancePortfolio</h1>
                </div>

                <div className="flex items-center gap-6">
                  {syncStatus !== 'idle' && (
                    <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                      syncStatus === 'syncing' ? 'bg-indigo-50 text-indigo-600' : 
                      syncStatus === 'synced' ? 'bg-green-50 text-green-600' : 'bg-red-50 text-red-600'
                    }`}>
                      {syncStatus === 'syncing' ? <Loader2 className="animate-spin" size={12} /> : 
                       syncStatus === 'synced' ? <CloudCheck size={12} /> : <AlertTriangle size={12} />}
                      {syncStatus}
                    </div>
                  )}

                  <div className="hidden md:flex flex-col items-end border-r border-gray-100 pr-6">
                    <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Authenticated As</span>
                    <span className="text-xs font-bold text-gray-900 truncate max-w-[150px]">{userEmail}</span>
                  </div>

                  <div className="flex items-center gap-2">
                    <button onClick={state.view === 'editor' ? goToPreview : () => {}} className={`flex items-center gap-2.5 px-6 py-3 rounded-2xl font-bold text-sm transition-all ${state.view === 'landing' ? 'hidden' : 'bg-gray-900 text-white shadow-xl hover:bg-black'}`}>
                      <Eye size={18} /> Preview
                    </button>

                    <button onClick={handleLogout} className="w-12 h-12 flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all" title="Sign Out">
                      <LogOut size={20} />
                    </button>
                  </div>
                </div>
              </div>
            </header>
          )}

          <main className={state.view === 'preview' ? '' : 'max-w-7xl mx-auto px-6 py-16 lg:py-24'}>
            {state.view === 'landing' && (
              <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000">
                <div className="text-center max-w-4xl mx-auto mb-20 relative">
                  <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black tracking-widest uppercase mb-8 border border-indigo-100">
                    <Sparkles size={14} /> Design Your Future
                  </div>
                  <h2 className="text-6xl md:text-8xl font-black text-gray-900 mb-8 tracking-tighter leading-[0.95] md:leading-[0.9]">
                    Showcase your <br/><span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-purple-600">creative soul.</span>
                  </h2>
                  <p className="text-xl text-gray-400 font-medium max-w-2xl mx-auto leading-relaxed">Choose a category to start your professional legacy.</p>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                  {CATEGORIES.map((cat) => (
                    <CategoryCard 
                      key={cat.id} 
                      id={cat.id} 
                      icon={cat.icon} 
                      description={cat.description} 
                      selected={state.data.category === cat.id} 
                      onSelect={(id) => {
                        setState(prev => ({ ...prev, data: { ...prev.data, category: id }, view: 'editor' }));
                        window.scrollTo(0,0);
                      }} 
                    />
                  ))}
                </div>
              </div>
            )}

            {state.view === 'editor' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                <div className="lg:col-span-8 animate-in fade-in slide-in-from-left-8 duration-700">
                  <button onClick={backToLanding} className="group inline-flex items-center gap-3 text-sm font-bold text-gray-400 hover:text-indigo-600 mb-10 transition-colors">
                    <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /> 
                    <span className="uppercase tracking-widest text-[10px] font-black">Change Domain</span>
                  </button>
