                      className={`group cursor-pointer p-8 rounded-[2.5rem] border-2 transition-all duration-500 overflow-hidden relative ${state.theme === t ? 'border-indigo-600 bg-white shadow-2xl scale-[1.02]' : 'border-white bg-white/40 hover:bg-white/80 hover:border-indigo-100'}`}
