            {state.view === 'preview' && (
              <div className="relative animate-in fade-in duration-1000">
                <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-white/95 backdrop-blur-2xl px-10 py-8 rounded-[3.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.25)] border border-white/50 w-[95%] max-w-4xl flex flex-col gap-8 transition-all duration-700 hover:shadow-[0_50px_120px_rgba(79,70,229,0.2)]">
                  <div className="flex flex-col md:flex-row items-center justify-between w-full gap-6">
