}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import ThemeSelector from './components/ThemeSelector';
import { supabase } from './services/supabase';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  Monitor, 
  Eye, 
  // Add EyeOff to imports
  EyeOff,
  Download,
  Share2,
  Check,
  Zap,
  Lock,
  Mail,
  ArrowRight,
  ShieldCheck,
  Loader2,
  LogOut,
  AlertTriangle,
  UserCheck,
  UserPlus,
  Palette,
  Layers
} from 'lucide-react';

export default function App() {
  const [state, setState] = useState<AppState>({
    view: 'login',
    data: INITIAL_DATA,
    theme: 'minimal',
  });

  const [isInitializing, setIsInitializing] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [isSignUp, setIsSignUp] = useState(false);
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [isPublishing, setIsPublishing] = useState(false);
  const [hasPublished, setHasPublished] = useState(false);
  const [copied, setCopied] = useState(false);

  const isInitialLoad = useRef(true);

  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle();

      if (error) {
        setErrorMessage(error.message);
        setSyncStatus('error');
      } else if (data) {
        setState(prev => ({
          ...prev,
          data: data.content || INITIAL_DATA,
          theme: (data.theme as Theme) || 'minimal',
          view: 'landing'
        }));
        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 2000);
      } else {
        setState(prev => ({ ...prev, view: 'landing' }));
        setSyncStatus('idle');
      }
    } catch (err: any) {
      setErrorMessage("Could not connect to Supabase.");
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
      setIsInitializing(false);
    }
  };

  useEffect(() => {
    const checkSession = async () => {
      const params = new URLSearchParams(window.location.search);
      const shared = params.get('p');
      if (shared) {
        try {
          const decoded = JSON.parse(decodeURIComponent(escape(atob(shared))));
          if (decoded.data) {
            setState(prev => ({
              ...prev,
              data: decoded.data,
              theme: decoded.theme || 'minimal',
              view: 'preview'
            }));
            setIsInitializing(false);
            return;
          }
        } catch (e) {
          console.error("Link decode error", e);
        }
      }

      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        fetchUserPortfolio(session.user.id);
      } else {
        setIsInitializing(false);
      }
    };

    checkSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        if (event === 'SIGNED_IN' || isInitialLoad.current) {
          fetchUserPortfolio(session.user.id);
        }
      } else {
        setUserId(null);
        setUserEmail(null);
        isInitialLoad.current = true;
        const params = new URLSearchParams(window.location.search);
        if (!params.has('p')) {
          setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
        }
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'login' || state.view === 'preview') return;

    const timer = setTimeout(() => {
      performSync();
    }, 1500);

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const performSync = async () => {
    if (!userId) return;
    setSyncStatus('syncing');
    try {
      const { error } = await supabase.from('portfolios').upsert({
        user_id: userId,
        content: state.data,
        theme: state.theme,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id' });

      if (error) throw error;
      setSyncStatus('synced');
      setTimeout(() => setSyncStatus('idle'), 3000);
      return true;
    } catch (err: any) {
      setSyncStatus('error');
      setErrorMessage(err.message || "Failed to sync to cloud.");
      return false;
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
        setSuccessMessage("Account created! Please verify your email.");
        setIsSignUp(false);
        setLoginPass('');
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      if (err.message?.includes('rate limit exceeded')) {
        setErrorMessage("Email rate limit exceeded. Supabase only allows 3 emails per hour on the free tier.");
      } else {
        setErrorMessage(err.message || "Authentication failed.");
      }
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  const handleDownload = () => {
    const { fullName, tagline, about, email, location, skills, projects } = state.data;
    const currentTheme = state.theme;

    // Mapping of theme to specific CSS and Layout logic
    const themeConfigs: Record<Theme, { bodyClass: string, cardClass: string, titleClass: string, accentColor: string, font: string }> = {
      minimal: {
        bodyClass: 'bg-white text-slate-800',
        cardClass: 'bg-slate-50 border border-slate-100 rounded-2xl p-8',
        titleClass: 'text-6xl font-black tracking-tight',
        accentColor: 'indigo-600',
        font: 'Plus Jakarta Sans'
      },
      modern: {
        bodyClass: 'bg-slate-950 text-slate-100',
        cardClass: 'bg-slate-900 border border-slate-800 rounded-3xl p-8',
        titleClass: 'text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-cyan-400',
        accentColor: 'cyan-400',
        font: 'Plus Jakarta Sans'
      },
      glass: {
        bodyClass: 'bg-indigo-600 text-white',
        cardClass: 'bg-white/10 backdrop-blur-xl border border-white/20 rounded-[2rem] p-8',
        titleClass: 'text-6xl font-bold tracking-tight',
        accentColor: 'white',
        font: 'Plus Jakarta Sans'
      },
      bold: {
        bodyClass: 'bg-yellow-400 text-black',
        cardClass: 'bg-white border-4 border-black rounded-none shadow-[10px_10px_0px_0px_rgba(0,0,0,1)] p-8',
        titleClass: 'text-7xl font-black uppercase tracking-tighter',
        accentColor: 'black',
        font: 'Plus Jakarta Sans'
      },
      classic: {
        bodyClass: 'bg-stone-50 text-stone-900',
        cardClass: 'bg-transparent border-b border-stone-200 pb-12 mb-12 last:border-0',
        titleClass: 'text-6xl font-normal italic',
        accentColor: 'stone-900',
        font: 'Playfair Display'
      }
    };

    const config = themeConfigs[currentTheme];

    const htmlContent = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${fullName} | Portfolio</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;800&family=Playfair+Display:ital,wght@0,400;1,400&display=swap" rel="stylesheet">
    <style>
        body { font-family: '${config.font}', sans-serif; }
        .accent-text { color: ${config.accentColor === 'black' ? '#000' : config.accentColor === 'white' ? '#fff' : '#4f46e5'}; }
        .accent-bg { background-color: ${config.accentColor === 'black' ? '#000' : config.accentColor === 'white' ? '#fff' : '#4f46e5'}; }
    </style>
</head>
<body class="${config.bodyClass} min-h-screen">
    <header class="py-32 px-8 text-center">
        <h1 class="${config.titleClass} mb-6">${fullName}</h1>
        <p class="text-xl opacity-60 max-w-2xl mx-auto font-medium leading-relaxed">${tagline}</p>
        <div class="mt-12 flex justify-center gap-8 text-[10px] font-black uppercase tracking-widest opacity-40">
            <span>${email}</span>
            <span>•</span>
            <span>${location}</span>
        </div>
    </header>
    <main class="max-w-5xl mx-auto py-20 px-8">
        <section class="mb-32">
            <h2 class="text-[10px] font-black uppercase tracking-[0.3em] opacity-40 mb-8">About Me</h2>
            <p class="text-3xl leading-snug font-medium whitespace-pre-wrap">${about}</p>
        </section>

        <section class="mb-32">
            <h2 class="text-[10px] font-black uppercase tracking-[0.3em] opacity-40 mb-12">Expertise</h2>
            <div class="flex flex-wrap gap-4">
                ${skills.map(s => `<span class="px-6 py-3 ${currentTheme === 'bold' ? 'bg-black text-white' : 'bg-current/5 border border-current/10'} rounded-2xl text-sm font-bold shadow-sm">${s.name}</span>`).join('')}
            </div>
        </section>

        <section class="mb-32">
            <h2 class="text-[10px] font-black uppercase tracking-[0.3em] opacity-40 mb-16">Featured Work</h2>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-10">
                ${projects.map(p => `
                    <div class="${config.cardClass}">
                        <h3 class="text-2xl font-black mb-4">${p.title}</h3>
                        <p class="opacity-60 mb-8 leading-relaxed">${p.description}</p>
                        ${p.link ? `<a href="${p.link}" target="_blank" class="inline-flex items-center gap-2 font-black uppercase tracking-widest text-[10px] border-b-2 border-current pb-1">View Project &rarr;</a>` : ''}
                    </div>
                `).join('')}
            </div>
        </section>
    </main>
    <footer class="py-24 text-center border-t border-current/10 opacity-30 text-[10px] font-black uppercase tracking-widest">
        © ${new Date().getFullYear()} ${fullName}. Built with FreelancePortfolio.
    </footer>
</body>
</html>`;

    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fullName.replace(/\s+/g, '_')}_Portfolio.html`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleShare = () => {
    const payload = btoa(unescape(encodeURIComponent(JSON.stringify({ data: state.data, theme: state.theme }))));
    const url = `${window.location.origin}${window.location.pathname}?p=${payload}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    const success = await performSync();
    if (success) setHasPublished(true);
    setIsPublishing(false);
  };

  const updateData = (data: PortfolioData) => setState(prev => ({ ...prev, data }));
  const setTheme = (theme: Theme) => setState(prev => ({ ...prev, theme }));
  const goToThemeSelection = () => setState(prev => ({ ...prev, view: 'theme-selection' }));
  const goToPreview = () => setState(prev => ({ ...prev, view: 'preview' }));
  const backToEditor = () => setState(prev => ({ ...prev, view: 'editor' }));
  const backToLanding = () => setState(prev => ({ ...prev, view: 'landing' }));

  if (isInitializing) {
