                  <div className="flex items-center gap-3 border-l border-gray-100 pl-6">
                    {userId ? (
                      <>
                        <button onClick={goToProfile} className={`w-11 h-11 rounded-full flex items-center justify-center transition-all ${state.view === 'profile' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-gray-50 text-gray-400 hover:bg-indigo-50 hover:text-indigo-600'}`} title="Dashboard"><User size={22} /></button>
                        <button onClick={handleLogout} className="w-11 h-11 flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-all" title="Sign Out"><LogOut size={20} /></button>
