                    ) : (
                      <button onClick={() => setShowAuthModal(true)} className="px-6 py-2.5 bg-indigo-600 text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-indigo-700 transition-all">Sign In</button>
