          <main className={state.view === 'preview' ? '' : 'max-w-7xl mx-auto px-6 py-16 lg:py-24'}>
            {state.view === 'profile' && userId && (
              <div>
                <div className="flex flex-col lg:flex-row justify-between items-start gap-12 mb-16">
                  <div className="flex-1">
                    <h2 className="text-5xl font-black text-gray-900 mb-4 tracking-tighter italic uppercase flex items-center gap-4"><LayoutDashboard size={40} className="text-indigo-600" />Studio Dashboard</h2>
                    <p className="text-xl text-gray-400 font-medium leading-relaxed">Managing portfolio for <span className="text-indigo-600 font-black">{state.data.fullName || userEmail?.split('@')[0]}</span>.</p>
                  </div>
                  <div className="flex items-center gap-4 bg-white px-6 py-4 rounded-[2rem] border border-gray-100 shadow-sm">
                    <div className="w-10 h-10 bg-green-50 text-green-600 rounded-xl flex items-center justify-center"><Activity size={20} className="animate-pulse" /></div>
                    <div><span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-400">Status</span><p className="text-xs font-bold text-gray-900">Site is Live</p></div>
