                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <button onClick={goToEditor} className="group flex flex-col items-start p-10 bg-white rounded-[2.5rem] border-2 border-transparent hover:border-indigo-600 shadow-xl shadow-indigo-100/10 transition-all duration-500 text-left"><div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-[1.5rem] flex items-center justify-center mb-8 group-hover:scale-110 group-hover:rotate-3 transition-all"><Edit3 size={32} /></div><h3 className="text-2xl font-black uppercase tracking-tighter italic mb-2">Edit Content</h3><p className="text-gray-400 text-sm font-medium">Update your skills, projects, and bio narrative.</p></button>
                      <button onClick={goToThemeSelection} className="group flex flex-col items-start p-10 bg-white rounded-[2.5rem] border-2 border-transparent hover:border-indigo-600 shadow-xl shadow-indigo-100/10 transition-all duration-500 text-left"><div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-[1.5rem] flex items-center justify-center mb-8 group-hover:scale-110 group-hover:rotate-3 transition-all"><Palette size={32} /></div><h3 className="text-2xl font-black uppercase tracking-tighter italic mb-2">Design Suite</h3><p className="text-gray-400 text-sm font-medium">Change themes, typography, and visual aesthetics.</p></button>
