                      <div className="aspect-[3/4] rounded-[2rem] overflow-hidden border-4 border-gray-900 bg-gray-50 relative shadow-2xl group cursor-pointer" onClick={goToPreview}>
                        <div className="scale-[0.38] origin-top-left w-[263%] h-[263%]"><PortfolioPreview data={state.data} theme={state.theme} /></div>
