              </div>
            )}

            {state.view === 'landing' && (
              <div>
                <div className="text-center max-w-4xl mx-auto mb-20 relative">
                  <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black tracking-widest uppercase mb-8 border border-indigo-100"><Sparkles size={14} /> Design Your Future</div>
                  <h2 className="text-6xl md:text-8xl font-black text-gray-900 mb-8 tracking-tighter leading-[0.95]">Showcase your <br/><span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-purple-600">creative soul.</span></h2>
                  <p className="text-xl text-gray-400 font-medium max-w-2xl mx-auto leading-relaxed">Choose a category to start your professional legacy.</p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                  {CATEGORIES.map((cat) => (
                    <CategoryCard key={cat.id} id={cat.id} icon={cat.icon} description={cat.description} selected={state.data.category === cat.id} onSelect={(id) => { setState(prev => ({ ...prev, data: { ...prev.data, category: id }, view: 'editor' })); window.scrollTo(0,0); }} />
                  ))}
                </div>
