            )}

            {state.view === 'editor' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                <div className="lg:col-span-8">
                  <button onClick={backToLanding} className="group inline-flex items-center gap-3 text-sm font-bold text-gray-400 hover:text-indigo-600 mb-10 transition-colors"><ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform" /><span className="uppercase tracking-widest text-[10px] font-black">Back to Domain</span></button>
                  <EditorForm data={state.data} onChange={updateData} onNext={handleGenerateClick} />
                </div>
                <div className="lg:col-span-4 hidden lg:block">
                  <div className="sticky top-32">
                    <div className="bg-white/70 backdrop-blur-md p-8 rounded-[2.5rem] border border-white shadow-2xl">
                      <h4 className="font-black text-gray-900 uppercase tracking-tighter flex items-center gap-2 italic mb-6"><Monitor size={20} className="text-indigo-600" /> Live Canvas</h4>
                      <div className="aspect-[3/4] rounded-2xl overflow-hidden border-4 border-gray-900 bg-gray-50 relative shadow-2xl"><div className="scale-[0.38] origin-top-left w-[263%] h-[263%]"><PortfolioPreview data={state.data} theme={state.theme} /></div></div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {state.view === 'theme-selection' && (
              <div>
                <button onClick={backToEditor} className="group inline-flex items-center gap-3 text-sm font-bold text-gray-400 hover:text-indigo-600 mb-10 transition-colors"><ArrowLeft size={16} /><span className="uppercase tracking-widest text-[10px] font-black">Back to Identity</span></button>
                <div className="mb-20">
                  <h2 className="text-5xl font-black text-gray-900 mb-4 tracking-tighter italic uppercase flex items-center gap-4"><Palette size={40} className="text-indigo-600" />Visual Aesthetics</h2>
                  <p className="text-xl text-gray-400 font-medium">Choose the interface that matches your personal brand.</p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-20">
                  {(['minimal', 'modern', 'glass', 'bold', 'classic', 'vibrant'] as Theme[]).map((t) => (
                    <div key={t} onClick={() => setTheme(t)} className={`group cursor-pointer p-8 rounded-[2.5rem] border-2 transition-all duration-500 overflow-hidden relative ${state.theme === t ? 'border-indigo-600 bg-white shadow-2xl scale-[1.02]' : 'border-white bg-white/40 hover:bg-white/80 hover:border-indigo-100'}`}><div className="flex justify-between items-start mb-10"><h3 className="text-2xl font-black uppercase tracking-tighter italic">{t}</h3>{state.theme === t && <div className="w-8 h-8 bg-indigo-600 text-white rounded-full flex items-center justify-center shadow-lg"><Check size={16} /></div>}</div><div className="aspect-[4/3] rounded-2xl overflow-hidden border border-gray-100 bg-gray-50 relative"><div className="scale-[0.25] origin-top-left w-[400%] h-[400%]"><PortfolioPreview data={state.data} theme={t} /></div></div></div>
                  ))}
                </div>
                <div className="flex justify-center"><button onClick={handlePreviewClick} className="group bg-indigo-600 text-white px-20 py-6 rounded-[2rem] font-black uppercase tracking-[0.2em] text-sm shadow-2xl hover:bg-indigo-700 transition-all flex items-center gap-4">PREVIEW LIVE <Eye size={20} className="group-hover:scale-110 transition-transform" /></button></div>
              </div>
            )}

            {state.view === 'preview' && (
              <div className="relative">
                <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-white/95 backdrop-blur-2xl px-10 py-8 rounded-[3.5rem] shadow-[0_40px_100px_rgba(0,0,0,0.25)] border border-white/50 w-[95%] max-w-4xl flex flex-col gap-8">
                  <div className="flex flex-col md:flex-row items-center justify-between w-full gap-6">
                    <div className="flex items-center gap-5">
                      <button onClick={goToThemeSelection} className="w-14 h-14 flex items-center justify-center bg-gray-50 hover:bg-gray-100 rounded-[1.5rem] text-gray-500 transition-all"><ArrowLeft size={28} /></button>
                      <div><h5 className="font-black uppercase tracking-tighter text-2xl leading-none">Publishing</h5><p className="text-[11px] font-black text-gray-400 uppercase tracking-[0.2em] mt-2">Ready for deployment</p></div>
                    </div>
                    <div className="flex items-center gap-3">
                      {!hasPublished ? (
                        <button onClick={handlePublish} disabled={isPublishing} className="flex items-center gap-3 px-10 py-4 bg-indigo-600 text-white rounded-[1.5rem] text-sm font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-700 disabled:opacity-50">{isPublishing ? <Loader2 size={18} className="animate-spin" /> : <Zap size={18} />}Save & Publish</button>
                      ) : (
                        <div className="flex items-center gap-3">
                          <button onClick={handleDownload} className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-[1.5rem] text-sm font-black uppercase shadow-xl"><Download size={18} /> HTML</button>
                          <button onClick={handleShare} className={`flex items-center gap-3 px-8 py-4 rounded-[1.5rem] text-sm font-black uppercase shadow-xl ${copied ? 'bg-green-500 text-white' : 'bg-indigo-600 text-white'}`}>{copied ? <Check size={18} /> : <Share2 size={18} />}{copied ? 'Copied' : 'Share'}</button>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
                <div className="min-h-screen"><PortfolioPreview data={state.data} theme={state.theme} /></div>
                <div className="h-64"></div>
              </div>
            )}
          </main>

          {state.view !== 'preview' && (
            <footer className="bg-white border-t border-gray-100 py-24 px-6 text-center">
              <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-12">
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-100"><Rocket size={24} /></div>
                  <h1 className="text-2xl font-black tracking-tighter leading-none text-slate-900">FreelancePortfolio</h1>
                </div>
                <div className="flex flex-col md:flex-row items-center gap-10">
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-gray-400"><ShieldCheck size={14} className="text-green-500" /> AES-256 Cloud Sync Active</div>
                  <p className="text-xs font-bold text-gray-300 uppercase tracking-widest">© {new Date().getFullYear()} FreelancePortfolio.</p>
                </div>
              </div>
            </footer>
          )}
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import ThemeSelector from './components/ThemeSelector';
import { supabase } from './services/supabase';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  Monitor, 
  Eye, 
  EyeOff,
  Download,
  Share2,
  Check,
  Zap,
  Lock,
  Mail,
  ArrowRight,
  ShieldCheck,
  Loader2,
  LogOut,
  AlertTriangle,
  UserCheck,
  Palette,
  LayoutDashboard,
  Edit3,
  User,
  Activity,
  X,
  ChevronRight
} from 'lucide-react';

export default function App() {
  const [state, setState] = useState<AppState>({
    view: 'login', // App starts with login page
    data: INITIAL_DATA,
    theme: 'minimal',
  });

  const [isInitializing, setIsInitializing] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [isSignUp, setIsSignUp] = useState(false);
  const [loginName, setLoginName] = useState('');
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [isPublishing, setIsPublishing] = useState(false);
  const [hasPublished, setHasPublished] = useState(false);
  const [copied, setCopied] = useState(false);

  const [showAuthModal, setShowAuthModal] = useState(false);
  const [pendingAction, setPendingAction] = useState<'theme-selection' | 'preview' | null>(null);

  const isInitialLoad = useRef(true);

  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    setErrorMessage(null);
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle();

      if (error) {
        setErrorMessage(error.message);
        setSyncStatus('error');
      } else if (data && data.content) {
        setState(prev => ({
          ...prev,
          data: data.content || INITIAL_DATA,
          theme: (data.theme as Theme) || 'minimal'
        }));
        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 2000);
      }
    } catch (err: any) {
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
    }
  };

  // 1. Initial Mount Check - Only runs once
  useEffect(() => {
    const checkSession = async () => {
      const params = new URLSearchParams(window.location.search);
      const shared = params.get('p');
      if (shared) {
        try {
          const decoded = JSON.parse(decodeURIComponent(escape(atob(shared))));
          if (decoded.data) {
            setState(prev => ({
              ...prev,
              data: decoded.data,
              theme: decoded.theme || 'minimal',
              view: 'preview'
            }));
            setIsInitializing(false);
            return;
          }
        } catch (e) {
          console.error("Link decode error", e);
        }
      }

      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        await fetchUserPortfolio(session.user.id);
        setState(prev => ({ ...prev, view: 'landing' }));
      }
      setIsInitializing(false);
    };

    checkSession();
  }, []);

  // 2. Auth State Listener - Responds to live auth events
  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);

        if (event === 'SIGNED_IN') {
          await fetchUserPortfolio(session.user.id);

          // Only perform automatic view switching if we are on login or have a pending action
          setState(prev => {
            if (pendingAction === 'theme-selection') return { ...prev, view: 'theme-selection' };
            if (pendingAction === 'preview') return { ...prev, view: 'preview' };
            if (prev.view === 'login') return { ...prev, view: 'landing' };
            return prev;
          });

          setPendingAction(null);
          setShowAuthModal(false);
        }
      } else {
        setUserId(null);
        setUserEmail(null);
        isInitialLoad.current = true;
      }
    });

    return () => subscription.unsubscribe();
  }, [pendingAction]);

  // 3. Cloud Sync - Debounced updates
  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'preview') return;

    const timer = setTimeout(() => {
      performSync();
    }, 1500);

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const performSync = async () => {
    if (!userId) return;
    setSyncStatus('syncing');
    try {
      const { error } = await supabase.from('portfolios').upsert({
        user_id: userId,
        content: state.data,
        theme: state.theme,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id' });

      if (error) throw error;
      setSyncStatus('synced');
      setTimeout(() => setSyncStatus('idle'), 3000);
      return true;
    } catch (err: any) {
      setSyncStatus('error');
      return false;
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
          options: {
            data: {
              full_name: loginName,
            }
          }
        });
        if (error) throw error;
        setSuccessMessage("Account created! Please verify your email.");
        if (!state.data.fullName && loginName) {
           updateData({...state.data, fullName: loginName});
        }
        setIsSignUp(false);
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      setErrorMessage(err.message || "Authentication failed.");
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
  };

  const handleDownload = () => {
    const { fullName, tagline, about, email, location, skills, projects } = state.data;
    const currentTheme = state.theme;

    const themeConfigs: Record<Theme, { bodyClass: string, cardClass: string, titleClass: string, accentColor: string, font: string }> = {
      minimal: {
        bodyClass: 'bg-white text-slate-800',
        cardClass: 'bg-slate-50 border border-slate-100 rounded-2xl p-8',
        titleClass: 'text-6xl font-black tracking-tight',
        accentColor: 'indigo-600',
        font: 'Plus Jakarta Sans'
      },
      modern: {
        bodyClass: 'bg-slate-950 text-slate-100',
        cardClass: 'bg-slate-900 border border-slate-800 rounded-3xl p-8',
        titleClass: 'text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-cyan-400',
        accentColor: 'cyan-400',
        font: 'Plus Jakarta Sans'
      },
      glass: {
