                  <h2 className="text-7xl md:text-9xl font-black text-slate-900 mb-10 tracking-tighter leading-[0.9] italic">Choose your <br/><span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 via-rose-500 to-amber-500">creative domain.</span></h2>
                  <p className="text-2xl text-slate-400 font-medium max-w-3xl mx-auto leading-relaxed">Select the industry that matches your expertise to begin crafting your high-end portfolio studio.</p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
                  {CATEGORIES.map((cat) => (
                    <CategoryCard 
                      key={cat.id} 
                      id={cat.id} 
                      icon={cat.icon} 
                      description={cat.description} 
                      color={cat.color}
                      bgLight={cat.bgLight}
                      selected={state.data.category === cat.id} 
                      onSelect={(id) => { 
                        setState(prev => ({ ...prev, data: { ...prev.data, category: id }, view: 'editor' })); 
                        window.scrollTo(0,0); 
                      }} 
                    />
                  ))}
                </div>
              </div>
            )}

            {state.view === 'editor' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-16">
                <div className="lg:col-span-8">
                  <button onClick={backToLanding} className="group inline-flex items-center gap-4 text-sm font-bold text-slate-400 hover:text-indigo-600 mb-14 transition-colors"><ArrowLeft size={20} className="group-hover:-translate-x-2 transition-transform" /><span className="uppercase tracking-[0.4em] text-[11px] font-black">Back to Domain</span></button>
                  <EditorForm data={state.data} onChange={updateData} onNext={handleGenerateClick} />
                </div>
                <div className="lg:col-span-4 hidden lg:block">
                  <div className="sticky top-40">
                    <div className="bg-white/80 backdrop-blur-3xl p-10 rounded-[3.5rem] border border-white shadow-3xl">
                      <h4 className="font-black text-slate-900 uppercase tracking-tighter flex items-center gap-4 italic mb-10 text-xl"><Monitor size={28} className="text-indigo-600" /> Multi-Device Studio</h4>
                      <div className="aspect-[3/4] rounded-[2rem] overflow-hidden border-8 border-slate-900 bg-slate-50 relative shadow-2xl"><div className="scale-[0.38] origin-top-left w-[263%] h-[263%]"><PortfolioPreview data={state.data} theme={state.theme} /></div></div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {state.view === 'theme-selection' && (
              <div>
                <button onClick={backToEditor} className="group inline-flex items-center gap-4 text-sm font-bold text-slate-400 hover:text-indigo-600 mb-14 transition-colors"><ArrowLeft size={20} /><span className="uppercase tracking-[0.4em] text-[11px] font-black">Back to Narrative</span></button>
                <div className="mb-24">
                  <h2 className="text-7xl font-black text-slate-900 mb-6 tracking-tighter italic uppercase flex items-center gap-8"><Palette size={64} className="text-indigo-600" />Visual Aesthetic</h2>
                  <p className="text-2xl text-slate-400 font-medium">Choose a layout that resonates with your personal brand identity.</p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-12 mb-24">
                  {(['minimal', 'modern', 'glass', 'bold', 'classic', 'vibrant'] as Theme[]).map((t) => (
                    <div key={t} onClick={() => setTheme(t)} className={`group cursor-pointer p-10 rounded-[3.5rem] border-4 transition-all duration-500 overflow-hidden relative ${state.theme === t ? 'border-indigo-600 bg-white shadow-3xl scale-[1.03]' : 'border-white bg-white/40 hover:bg-white hover:border-slate-100'}`}><div className="flex justify-between items-start mb-12"><h3 className="text-3xl font-black uppercase tracking-tighter italic">{t}</h3>{state.theme === t && <div className="w-10 h-10 bg-indigo-600 text-white rounded-full flex items-center justify-center shadow-lg"><Check size={20} /></div>}</div><div className="aspect-[4/3] rounded-[2rem] overflow-hidden border-2 border-slate-100 bg-slate-50 relative"><div className="scale-[0.25] origin-top-left w-[400%] h-[400%]"><PortfolioPreview data={state.data} theme={t} /></div></div></div>
                  ))}
                </div>
                <div className="flex justify-center"><button onClick={handlePreviewClick} className="group bg-slate-900 text-white px-24 py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] text-sm shadow-3xl hover:shadow-indigo-500/30 hover:-translate-y-2 transition-all active:scale-95 flex items-center gap-6">LAUNCH PREVIEW <Eye size={24} className="group-hover:scale-110 transition-transform" /></button></div>
              </div>
            )}

            {state.view === 'preview' && (
              <div className="relative">
                <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-white/95 backdrop-blur-3xl px-12 py-10 rounded-[4rem] shadow-[0_40px_100px_rgba(0,0,0,0.2)] border border-white/50 w-[95%] max-w-5xl flex flex-col gap-10">
                  <div className="flex flex-col md:flex-row items-center justify-between w-full gap-8">
                    <div className="flex items-center gap-6">
                      <button onClick={goToThemeSelection} className="w-16 h-16 flex items-center justify-center bg-slate-50 hover:bg-slate-100 rounded-[1.8rem] text-slate-500 transition-all hover:scale-105 active:scale-95"><ArrowLeft size={32} /></button>
                      <div><h5 className="font-black uppercase tracking-tighter text-3xl leading-none italic">Publish Studio</h5><p className="text-[12px] font-black text-slate-400 uppercase tracking-[0.4em] mt-3 italic">Finalize your professional portal</p></div>
                    </div>
                    <div className="flex items-center gap-4">
                      {!hasPublished ? (
                        <button onClick={handlePublish} disabled={isPublishing} className="flex items-center gap-4 px-12 py-5 bg-gradient-to-r from-indigo-600 to-indigo-700 text-white rounded-[1.8rem] text-sm font-black uppercase tracking-[0.2em] shadow-3xl hover:shadow-indigo-500/40 hover:-translate-y-1 active:scale-95 disabled:opacity-50">{isPublishing ? <Loader2 size={24} className="animate-spin" /> : <Zap size={24} />}SAVE & GO LIVE</button>
                      ) : (
                        <div className="flex items-center gap-4">
                          <button onClick={handleDownload} className="flex items-center gap-4 px-10 py-5 bg-slate-900 text-white rounded-[1.8rem] text-sm font-black uppercase tracking-[0.2em] shadow-2xl hover:-translate-y-1 active:scale-95"><Download size={24} /> EXPORT HTML</button>
                          <button onClick={handleShare} className={`flex items-center gap-4 px-10 py-5 rounded-[1.8rem] text-sm font-black uppercase tracking-[0.2em] shadow-2xl hover:-translate-y-1 active:scale-95 transition-all ${copied ? 'bg-emerald-500 text-white' : 'bg-indigo-600 text-white'}`}>{copied ? <Check size={24} /> : <Share2 size={24} />}{copied ? 'COPIED' : 'SHARE LINK'}</button>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
                <div className="min-h-screen"><PortfolioPreview data={state.data} theme={state.theme} /></div>
                <div className="h-64"></div>
              </div>
            )}
          </main>

          {state.view !== 'preview' && (
            <footer className="bg-white border-t border-slate-100 py-32 px-8 text-center">
              <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-16">
                <div className="flex items-center gap-5">
                  <div className="w-14 h-14 bg-gradient-to-tr from-indigo-600 to-purple-600 text-white rounded-[1.2rem] flex items-center justify-center shadow-xl"><Rocket size={28} /></div>
                  <h1 className="text-3xl font-black tracking-tighter leading-none text-slate-900 italic">FreelancePortfolio</h1>
                </div>
                <div className="flex flex-col md:flex-row items-center gap-12">
                  <div className="flex items-center gap-3 text-[11px] font-black uppercase tracking-[0.4em] text-slate-400"><ShieldCheck size={18} className="text-emerald-500" /> AES-256 PORTAL ENCRYPTION</div>
                  <p className="text-xs font-black text-slate-300 uppercase tracking-[0.4em] italic">© {new Date().getFullYear()} PORTFOLIO STUDIO.</p>
                </div>
              </div>
            </footer>
          )}
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import ThemeSelector from './components/ThemeSelector';
import { supabase } from './services/supabase';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  Monitor, 
  Eye, 
  EyeOff,
  Download,
  Share2,
  Check,
  Zap,
  Lock,
  Mail,
  ArrowRight,
  ShieldCheck,
  Loader2,
  LogOut,
  AlertTriangle,
  UserCheck,
  Palette,
  LayoutDashboard,
  Edit3,
  User,
  Activity,
  X,
  ChevronRight
} from 'lucide-react';

export default function App() {
  const [state, setState] = useState<AppState>({
    view: 'login',
    data: INITIAL_DATA,
    theme: 'minimal',
  });

  const [isInitializing, setIsInitializing] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [isSignUp, setIsSignUp] = useState(false);
  const [loginName, setLoginName] = useState('');
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [isPublishing, setIsPublishing] = useState(false);
  const [hasPublished, setHasPublished] = useState(false);
  const [copied, setCopied] = useState(false);

  const [showAuthModal, setShowAuthModal] = useState(false);
  const [pendingAction, setPendingAction] = useState<'theme-selection' | 'preview' | null>(null);

  const isInitialLoad = useRef(true);

  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle();

      if (error) throw error;

      if (data && data.content) {
        // Robust data merging to prevent undefined.map() crashes
        const mergedData: PortfolioData = {
          ...INITIAL_DATA,
          ...data.content,
          skills: data.content.skills || [],
          projects: data.content.projects || [],
          qualifications: data.content.qualifications || [],
          certifications: data.content.certifications || [],
          socials: { ...INITIAL_DATA.socials, ...(data.content.socials || {}) }
        };

        setState(prev => ({
          ...prev,
          data: mergedData,
          theme: (data.theme as Theme) || 'minimal'
        }));
        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 2000);
      }
    } catch (err: any) {
      console.error("Fetch error:", err);
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
    }
  };

  useEffect(() => {
    const checkSession = async () => {
      const params = new URLSearchParams(window.location.search);
      const shared = params.get('p');

      if (shared) {
        try {
          const decoded = JSON.parse(decodeURIComponent(escape(atob(shared))));
          if (decoded.data) {
            setState(prev => ({
              ...prev,
              data: decoded.data,
              theme: decoded.theme || 'minimal',
              view: 'preview'
            }));
            setIsInitializing(false);
            return;
          }
        } catch (e) {
          console.error("Decode error", e);
        }
      }

      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        await fetchUserPortfolio(session.user.id);
        setState(prev => ({ ...prev, view: 'landing' }));
      }
      setIsInitializing(false);
    };

    checkSession();
  }, []);

  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session) {
        const isNewUser = !userId;
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);

        // Only run fetch and navigation logic on legitimate sign-in events to prevent reset loops
        if (event === 'SIGNED_IN' && isNewUser) {
          await fetchUserPortfolio(session.user.id);

          setState(prev => {
            if (pendingAction === 'theme-selection') return { ...prev, view: 'theme-selection' };
            if (pendingAction === 'preview') return { ...prev, view: 'preview' };
            // Only force landing if we were stuck on the login screen
            if (prev.view === 'login') return { ...prev, view: 'landing' };
            return prev;
          });

          setPendingAction(null);
          setShowAuthModal(false);
        }
      } else {
        setUserId(null);
        setUserEmail(null);
        isInitialLoad.current = true;
      }
    });

    return () => subscription.unsubscribe();
  }, [userId, pendingAction]);

  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'preview') return;

    const timer = setTimeout(() => {
      performSync();
    }, 2000);

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const performSync = async () => {
    if (!userId) return;
    setSyncStatus('syncing');
    try {
      const { error } = await supabase.from('portfolios').upsert({
        user_id: userId,
        content: state.data,
        theme: state.theme,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id' });

      if (error) throw error;
      setSyncStatus('synced');
      setTimeout(() => setSyncStatus('idle'), 3000);
      return true;
    } catch (err: any) {
      setSyncStatus('error');
      return false;
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
          options: { data: { full_name: loginName } }
        });
        if (error) throw error;
        setSuccessMessage("Check your email to verify!");
        setIsSignUp(false);
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      setErrorMessage(err.message || "Auth failed.");
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
  };

  const updateData = (data: PortfolioData) => setState(prev => ({ ...prev, data }));
  const setTheme = (theme: Theme) => setState(prev => ({ ...prev, theme }));

  const handleShare = () => {
    const payload = btoa(unescape(encodeURIComponent(JSON.stringify({ data: state.data, theme: state.theme }))));
    const url = `${window.location.origin}${window.location.pathname}?p=${payload}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const html = `<!DOCTYPE html><html><head><title>${state.data.fullName}</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-10"><div class="max-w-3xl mx-auto bg-white p-12 rounded-3xl shadow-xl"><h1 class="text-5xl font-black mb-4">${state.data.fullName}</h1><p class="text-xl text-gray-500 mb-10">${state.data.tagline}</p><div class="prose lg:prose-xl">${state.data.about}</div></div></body></html>`;
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'portfolio.html';
    a.click();
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    const success = await performSync();
    if (success) setHasPublished(true);
    setIsPublishing(false);
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center">
        <div className="w-24 h-24 bg-gradient-to-tr from-indigo-600 via-purple-600 to-rose-600 text-white rounded-3xl flex items-center justify-center animate-bounce shadow-2xl shadow-indigo-200">
          <Rocket size={48} />
        </div>
        <p className="mt-8 text-sm font-black uppercase tracking-[0.5em] text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-rose-600 animate-pulse">Initializing Studio</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen selection:bg-rose-100 selection:text-rose-900">
      {state.view === 'login' ? (
        <div className="min-h-screen flex items-center justify-center p-6 relative overflow-hidden">
          <div className="max-w-xl w-full z-10 flex flex-col items-center">
            <div className="text-center mb-16">
              <div className="inline-flex items-center justify-center w-32 h-32 bg-gradient-to-tr from-indigo-600 via-rose-600 to-amber-500 text-white rounded-[3rem] shadow-[0_32px_64px_-16px_rgba(79,70,229,0.4)] mb-12">
                <Rocket size={64} className="animate-float" />
              </div>
              <h1 className="text-7xl md:text-8xl font-black tracking-tighter text-slate-900 mb-8">
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 via-rose-500 to-amber-500">FreelancePortfolio</span>
              </h1>
              <p className="text-2xl text-slate-500 font-medium max-w-md mx-auto">Vibrant tools for elite independent creators.</p>
            </div>

            <div className="bg-white/80 backdrop-blur-3xl p-12 rounded-[4rem] shadow-2xl border border-white w-full">
              <div className="flex gap-4 mb-12 p-2 bg-slate-100/50 rounded-[2rem]">
                <button onClick={() => setIsSignUp(false)} className={`flex-1 py-4 rounded-2xl text-xs font-black uppercase tracking-[0.2em] transition-all ${!isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>Sign In</button>
                <button onClick={() => setIsSignUp(true)} className={`flex-1 py-4 rounded-2xl text-xs font-black uppercase tracking-[0.2em] transition-all ${isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>Join</button>
              </div>

              {errorMessage && <div className="mb-8 p-6 bg-rose-50 border border-rose-100 text-rose-600 rounded-3xl text-xs font-bold uppercase flex items-center gap-3"><AlertTriangle size={18}/>{errorMessage}</div>}
              {successMessage && <div className="mb-8 p-6 bg-emerald-50 border border-emerald-100 text-emerald-600 rounded-3xl text-xs font-bold uppercase flex items-center gap-3"><UserCheck size={18}/>{successMessage}</div>}

              <form onSubmit={handleAuth} className="space-y-6">
                {isSignUp && (
                  <input type="text" required value={loginName} onChange={(e) => setLoginName(e.target.value)} className="w-full px-8 py-6 rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-xl" placeholder="Full Name"/>
                )}
                <input type="email" required value={loginEmail} onChange={(e) => setLoginEmail(e.target.value)} className="w-full px-8 py-6 rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-xl" placeholder="Email Address"/>
                <div className="relative">
                  <input type={showPass ? "text" : "password"} required value={loginPass} onChange={(e) => setLoginPass(e.target.value)} className="w-full px-8 py-6 rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-xl" placeholder="Password"/>
                  <button type="button" onClick={() => setShowPass(!showPass)} className="absolute inset-y-0 right-8 text-slate-300 hover:text-indigo-600">{showPass ? <EyeOff size={24}/> : <Eye size={24}/>}</button>
                </div>
                <button type="submit" disabled={isAuthLoading} className="w-full bg-gradient-to-r from-indigo-600 to-rose-600 text-white py-6 rounded-[2rem] font-black uppercase tracking-[0.3em] shadow-xl hover:shadow-indigo-500/40 transition-all">
                  {isAuthLoading ? <Loader2 size={24} className="animate-spin mx-auto"/> : (isSignUp ? "INITIALIZE" : "AUTHENTICATE")}
                </button>
                <button type="button" onClick={() => setState(prev => ({ ...prev, view: 'landing' }))} className="w-full py-6 rounded-[2rem] border-2 border-indigo-50 text-indigo-600 font-black uppercase tracking-[0.3em] text-xs hover:bg-indigo-50 transition-all flex items-center justify-center gap-4">
                  ENTER AS GUEST <ChevronRight size={20}/>
                </button>
              </form>
            </div>
          </div>
        </div>
      ) : (
        <>
          {state.view !== 'preview' && (
            <header className="bg-white/80 backdrop-blur-2xl border-b border-slate-100 sticky top-0 z-[60]">
              <div className="max-w-7xl mx-auto px-8 h-24 flex items-center justify-between">
                <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setState(prev => ({...prev, view: 'landing'}))}>
                  <div className="w-12 h-12 bg-gradient-to-tr from-indigo-600 to-purple-600 text-white rounded-[1.2rem] flex items-center justify-center shadow-lg group-hover:scale-110 transition-all">
                    <Rocket size={26} />
                  </div>
                  <h1 className="text-2xl font-black tracking-tighter text-slate-900 leading-none">FreelancePortfolio</h1>
                </div>
                <div className="flex items-center gap-6">
                  {userId && syncStatus !== 'idle' && (
                    <div className={`hidden md:flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest ${syncStatus === 'syncing' ? 'bg-indigo-50 text-indigo-600' : 'bg-emerald-50 text-emerald-600'}`}>
                      {syncStatus === 'syncing' ? <Loader2 className="animate-spin" size={14}/> : <Check size={14}/>} {syncStatus}
                    </div>
                  )}
                  {userId ? (
                    <div className="flex items-center gap-4">
                      <button onClick={() => setState(prev => ({...prev, view: 'profile'}))} className={`w-12 h-12 rounded-full flex items-center justify-center transition-all ${state.view === 'profile' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:text-indigo-600'}`}><User size={24}/></button>
                      <button onClick={handleLogout} className="w-12 h-12 flex items-center justify-center text-slate-400 hover:text-rose-500 rounded-full transition-all"><LogOut size={22}/></button>
                    </div>
                  ) : (
                    <button onClick={() => setShowAuthModal(true)} className="px-8 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-indigo-700 transition-all">Sign In</button>
                  )}
                </div>
              </div>
            </header>
          )}

          <main className={state.view === 'preview' ? '' : 'max-w-7xl mx-auto px-8 py-20'}>
            {state.view === 'landing' && (
              <div className="space-y-20">
                <div className="text-center max-w-4xl mx-auto">
                  <div className="inline-flex items-center gap-2 px-4 py-2 bg-rose-50 text-rose-600 rounded-full text-[10px] font-black tracking-widest uppercase mb-8 border border-rose-100"><Sparkles size={14}/> Design Your Legacy</div>
                  <h2 className="text-7xl md:text-8xl font-black text-slate-900 mb-8 tracking-tighter leading-none italic">Choose your <br/><span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 via-rose-500 to-amber-500">creative domain.</span></h2>
                  <p className="text-2xl text-slate-400 font-medium">Select the path that matches your professional soul.</p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-10">
                  {CATEGORIES.map((cat) => (
                    <CategoryCard 
                      key={cat.id} id={cat.id} icon={cat.icon} description={cat.description} 
                      color={cat.color} bgLight={cat.bgLight} selected={state.data.category === cat.id} 
                      onSelect={(id) => setState(prev => ({ ...prev, data: { ...prev.data, category: id }, view: 'editor' }))} 
                    />
                  ))}
                </div>
              </div>
            )}

            {state.view === 'editor' && (
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-16">
                <div className="lg:col-span-8">
                  <button onClick={() => setState(prev => ({...prev, view: 'landing'}))} className="group inline-flex items-center gap-4 text-sm font-bold text-slate-400 hover:text-indigo-600 mb-14 transition-colors">
                    <ArrowLeft size={20} className="group-hover:-translate-x-2 transition-transform" />
                    <span className="uppercase tracking-[0.4em] text-[11px] font-black">Back to Domain</span>
                  </button>
                  <EditorForm data={state.data} onChange={updateData} onNext={() => userId ? setState(prev => ({...prev, view: 'theme-selection'})) : setShowAuthModal(true)} />
                </div>
                <div className="lg:col-span-4 hidden lg:block">
                  <div className="sticky top-40 bg-white/80 backdrop-blur-3xl p-10 rounded-[3.5rem] border border-white shadow-2xl">
                    <h4 className="font-black text-slate-900 uppercase tracking-tighter flex items-center gap-4 italic mb-10 text-xl"><Monitor size={28} className="text-indigo-600" /> Multi-Device View</h4>
                    <div className="aspect-[3/4] rounded-[2rem] overflow-hidden border-8 border-slate-900 bg-slate-50 relative shadow-2xl">
                      <div className="scale-[0.38] origin-top-left w-[263%] h-[263%]"><PortfolioPreview data={state.data} theme={state.theme} /></div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {state.view === 'theme-selection' && (
              <div className="space-y-20">
                <div className="mb-24">
                  <h2 className="text-7xl font-black text-slate-900 mb-6 tracking-tighter italic uppercase flex items-center gap-8"><Palette size={64} className="text-indigo-600" />Visual Aesthetic</h2>
                  <p className="text-2xl text-slate-400 font-medium">Choose a layout that resonates with your brand identity.</p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
                  {(['minimal', 'modern', 'glass', 'bold', 'classic', 'vibrant'] as Theme[]).map((t) => (
                    <div key={t} onClick={() => setTheme(t)} className={`group cursor-pointer p-10 rounded-[3.5rem] border-4 transition-all overflow-hidden relative ${state.theme === t ? 'border-indigo-600 bg-white shadow-2xl scale-[1.03]' : 'border-white bg-white/40 hover:border-slate-100'}`}>
                      <div className="flex justify-between items-start mb-12"><h3 className="text-3xl font-black uppercase tracking-tighter italic">{t}</h3>{state.theme === t && <Check className="text-indigo-600" size={32}/>}</div>
                      <div className="aspect-[4/3] rounded-[2rem] overflow-hidden border-2 border-slate-100 bg-slate-50 relative">
                        <div className="scale-[0.25] origin-top-left w-[400%] h-[400%]"><PortfolioPreview data={state.data} theme={t} /></div>
                      </div>
                    </div>
                  ))}
                </div>
                <div className="flex justify-center"><button onClick={() => setState(prev => ({...prev, view: 'preview'}))} className="group bg-slate-900 text-white px-24 py-8 rounded-[2.5rem] font-black uppercase tracking-[0.3em] shadow-3xl hover:-translate-y-2 transition-all flex items-center gap-6">LAUNCH PREVIEW <Eye size={24}/></button></div>
              </div>
            )}

            {state.view === 'profile' && (
              <div className="space-y-16">
                <div className="flex flex-col lg:flex-row justify-between items-start gap-12 mb-20">
                  <div className="flex-1">
                    <h2 className="text-6xl font-black text-slate-900 mb-5 tracking-tighter italic uppercase flex items-center gap-6"><LayoutDashboard size={48} className="text-indigo-600" />Studio Dashboard</h2>
                    <p className="text-2xl text-slate-400 font-medium leading-relaxed">Identity: <span className="text-indigo-600 font-black italic">{state.data.fullName || userEmail}</span></p>
                  </div>
                  <div className="flex items-center gap-6 bg-white px-8 py-6 rounded-[2.5rem] border border-slate-100 shadow-sm">
                    <div className="w-14 h-14 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center animate-pulse"><Activity size={28}/></div>
                    <div><span className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-400">Live Status</span><p className="text-sm font-black text-slate-900 uppercase italic">Authenticated</p></div>
                  </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <button onClick={() => setState(prev => ({...prev, view: 'editor'}))} className="group p-12 bg-white rounded-[3rem] border-4 border-transparent hover:border-indigo-600 shadow-2xl transition-all text-left">
                    <div className="w-20 h-20 bg-indigo-50 text-indigo-600 rounded-[2rem] flex items-center justify-center mb-10 shadow-sm"><Edit3 size={40}/></div>
                    <h3 className="text-3xl font-black uppercase italic mb-4">Edit Core</h3>
                    <p className="text-slate-400">Refine your projects and narrative.</p>
                  </button>
                  <button onClick={() => setState(prev => ({...prev, view: 'theme-selection'}))} className="group p-12 bg-white rounded-[3rem] border-4 border-transparent hover:border-rose-500 shadow-2xl transition-all text-left">
                    <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-[2rem] flex items-center justify-center mb-10 shadow-sm"><Palette size={40}/></div>
                    <h3 className="text-3xl font-black uppercase italic mb-4">Aesthetics</h3>
                    <p className="text-slate-400">Switch themes and vibrant palettes.</p>
                  </button>
                </div>
              </div>
            )}

            {state.view === 'preview' && (
              <div className="relative">
                <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[100] bg-white/95 backdrop-blur-3xl px-12 py-8 rounded-[4rem] shadow-2xl border border-white/50 w-[95%] max-w-5xl flex items-center justify-between gap-8">
                  <div className="flex items-center gap-6">
                    <button onClick={() => setState(prev => ({...prev, view: 'theme-selection'}))} className="w-16 h-16 flex items-center justify-center bg-slate-50 hover:bg-slate-100 rounded-[1.8rem] transition-all"><ArrowLeft size={32}/></button>
                    <div><h5 className="font-black uppercase tracking-tighter text-2xl italic">Publish Studio</h5><p className="text-xs font-bold text-slate-400 italic">Finalize your professional portal</p></div>
                  </div>
                  <div className="flex gap-4">
                    {!hasPublished ? (
                      <button onClick={handlePublish} disabled={isPublishing} className="px-12 py-5 bg-gradient-to-r from-indigo-600 to-indigo-700 text-white rounded-[1.8rem] text-sm font-black uppercase tracking-[0.2em] shadow-xl hover:shadow-indigo-500/40 transition-all flex items-center gap-4">
                        {isPublishing ? <Loader2 className="animate-spin" size={24}/> : <Zap size={24}/>} SAVE & GO LIVE
                      </button>
                    ) : (
                      <div className="flex gap-4">
                        <button onClick={handleDownload} className="px-10 py-5 bg-slate-900 text-white rounded-[1.8rem] text-sm font-black uppercase shadow-xl">EXPORT HTML</button>
                        <button onClick={handleShare} className={`px-10 py-5 rounded-[1.8rem] text-sm font-black uppercase shadow-xl transition-all ${copied ? 'bg-emerald-500 text-white' : 'bg-indigo-600 text-white'}`}>
                          {copied ? <Check size={24}/> : <Share2 size={24}/>} {copied ? 'COPIED' : 'SHARE LINK'}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
                <div className="min-h-screen"><PortfolioPreview data={state.data} theme={state.theme} /></div>
                <div className="h-64"></div>
              </div>
            )}
          </main>

          {state.view !== 'preview' && (
            <footer className="bg-white border-t border-slate-100 py-32 px-8 text-center mt-auto">
              <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-16">
                <div className="flex items-center gap-5">
                  <div className="w-14 h-14 bg-gradient-to-tr from-indigo-600 to-purple-600 text-white rounded-[1.2rem] flex items-center justify-center shadow-xl"><Rocket size={28}/></div>
                  <h1 className="text-3xl font-black tracking-tighter text-slate-900 italic">FreelancePortfolio</h1>
                </div>
                <div className="flex items-center gap-3 text-[11px] font-black uppercase tracking-[0.4em] text-slate-400"><ShieldCheck size={18} className="text-emerald-500"/> AES-256 PORTAL ENCRYPTION</div>
              </div>
            </footer>
          )}

          {showAuthModal && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-md">
              <div className="max-w-md w-full bg-white rounded-[3rem] p-12 shadow-2xl relative">
                <button onClick={() => {setShowAuthModal(false); setPendingAction(null);}} className="absolute top-10 right-10 text-gray-400 hover:text-indigo-600"><X size={28}/></button>
                <div className="text-center mb-10"><Lock className="mx-auto text-indigo-600 mb-6" size={48}/><h2 className="text-4xl font-black tracking-tighter">Secure Account</h2></div>
                <form onSubmit={handleAuth} className="space-y-6">
                  <input type="email" required value={loginEmail} onChange={(e) => setLoginEmail(e.target.value)} className="w-full px-8 py-6 rounded-[2rem] border border-slate-100 bg-gray-50 focus:bg-white outline-none transition-all font-semibold" placeholder="Email"/>
                  <input type="password" required value={loginPass} onChange={(e) => setLoginPass(e.target.value)} className="w-full px-8 py-6 rounded-[2rem] border border-slate-100 bg-gray-50 focus:bg-white outline-none transition-all font-semibold" placeholder="Password"/>
                  <button type="submit" className="w-full bg-indigo-600 text-white py-6 rounded-[2rem] font-black uppercase tracking-widest shadow-xl">AUTHENTICATE</button>
                </form>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import ThemeSelector from './components/ThemeSelector';
import { supabase } from './services/supabase';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  Monitor, 
  Eye, 
  EyeOff,
  Download,
  Share2,
  Check,
  Zap,
  Lock,
  Mail,
  ArrowRight,
  ShieldCheck,
  Loader2,
  LogOut,
  AlertTriangle,
  UserCheck,
  Palette,
  LayoutDashboard,
  Edit3,
  User,
  Activity,
  X,
  ChevronRight
} from 'lucide-react';

export default function App() {
  const [state, setState] = useState<AppState>({
    view: 'login',
    data: INITIAL_DATA,
    theme: 'minimal',
  });

  const [isInitializing, setIsInitializing] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [isSignUp, setIsSignUp] = useState(false);
  const [loginName, setLoginName] = useState('');
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [isPublishing, setIsPublishing] = useState(false);
  const [hasPublished, setHasPublished] = useState(false);
  const [copied, setCopied] = useState(false);

  const [showAuthModal, setShowAuthModal] = useState(false);
  const [pendingAction, setPendingAction] = useState<'theme-selection' | 'preview' | null>(null);

  const isInitialLoad = useRef(true);

  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle();

      if (error) throw error;

      if (data && data.content) {
        const mergedData: PortfolioData = {
          ...INITIAL_DATA,
          ...data.content,
          skills: data.content.skills || [],
          projects: data.content.projects || [],
          qualifications: data.content.qualifications || [],
          certifications: data.content.certifications || [],
          socials: { ...INITIAL_DATA.socials, ...(data.content.socials || {}) }
        };

        setState(prev => ({
          ...prev,
          data: mergedData,
          theme: (data.theme as Theme) || 'minimal'
        }));
        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 2000);
      }
    } catch (err: any) {
      console.error("Fetch error:", err);
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
    }
  };

  useEffect(() => {
    const checkSession = async () => {
      const params = new URLSearchParams(window.location.search);
      const shared = params.get('p');

      if (shared) {
        try {
          const decoded = JSON.parse(decodeURIComponent(escape(atob(shared))));
          if (decoded.data) {
            setState(prev => ({
              ...prev,
              data: decoded.data,
              theme: decoded.theme || 'minimal',
              view: 'preview'
            }));
            setIsInitializing(false);
            return;
          }
        } catch (e) {
          console.error("Decode error", e);
        }
      }

      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        await fetchUserPortfolio(session.user.id);
        setState(prev => ({ ...prev, view: 'landing' }));
      }
      setIsInitializing(false);
    };

    checkSession();
  }, []);

  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session) {
        const isNewUser = !userId;
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);

        if (event === 'SIGNED_IN' && isNewUser) {
          await fetchUserPortfolio(session.user.id);

          setState(prev => {
            if (pendingAction === 'theme-selection') return { ...prev, view: 'theme-selection' };
            if (pendingAction === 'preview') return { ...prev, view: 'preview' };
            if (prev.view === 'login') return { ...prev, view: 'landing' };
            return prev;
          });

          setPendingAction(null);
          setShowAuthModal(false);
        }
      } else {
        setUserId(null);
        setUserEmail(null);
        isInitialLoad.current = true;
      }
    });

    return () => subscription.unsubscribe();
  }, [userId, pendingAction]);

  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'preview') return;

    const timer = setTimeout(() => {
      performSync();
    }, 2000);

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const performSync = async () => {
    if (!userId) return;
    setSyncStatus('syncing');
    try {
      const { error } = await supabase.from('portfolios').upsert({
        user_id: userId,
        content: state.data,
        theme: state.theme,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id' });

      if (error) throw error;
      setSyncStatus('synced');
      setTimeout(() => setSyncStatus('idle'), 3000);
      return true;
    } catch (err: any) {
      setSyncStatus('error');
      return false;
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
          options: { data: { full_name: loginName } }
        });
        if (error) throw error;
        setSuccessMessage("Check your email to verify!");
        setIsSignUp(false);
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      setErrorMessage(err.message || "Auth failed.");
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
  };

  const updateData = (data: PortfolioData) => setState(prev => ({ ...prev, data }));
  const setTheme = (theme: Theme) => setState(prev => ({ ...prev, theme }));

  const handleShare = () => {
    const payload = btoa(unescape(encodeURIComponent(JSON.stringify({ data: state.data, theme: state.theme }))));
    const url = `${window.location.origin}${window.location.pathname}?p=${payload}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const html = `<!DOCTYPE html><html><head><title>${state.data.fullName}</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-50 p-10"><div class="max-w-3xl mx-auto bg-white p-12 rounded-3xl shadow-xl"><h1 class="text-5xl font-black mb-4">${state.data.fullName}</h1><p class="text-xl text-gray-500 mb-10">${state.data.tagline}</p><div class="prose lg:prose-xl">${state.data.about}</div></div></body></html>`;
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'portfolio.html';
    a.click();
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    const success = await performSync();
    if (success) setHasPublished(true);
    setIsPublishing(false);
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-20 h-20 md:w-24 md:h-24 bg-gradient-to-tr from-indigo-600 via-purple-600 to-rose-600 text-white rounded-3xl flex items-center justify-center animate-bounce shadow-2xl shadow-indigo-200">
          <Rocket size={40} className="md:w-12 md:h-12" />
        </div>
        <p className="mt-8 text-xs md:text-sm font-black uppercase tracking-[0.4em] text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-rose-600 animate-pulse text-center">Initializing Studio</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen selection:bg-rose-100 selection:text-rose-900">
      {state.view === 'login' ? (
        <div className="min-h-screen flex items-center justify-center p-4 md:p-6 relative overflow-hidden">
          <div className="max-w-xl w-full z-10 flex flex-col items-center">
            <div className="text-center mb-8 md:mb-16 px-4">
              <div className="inline-flex items-center justify-center w-24 h-24 md:w-32 md:h-32 bg-gradient-to-tr from-indigo-600 via-rose-600 to-amber-500 text-white rounded-[2.5rem] md:rounded-[3rem] shadow-[0_32px_64px_-16px_rgba(79,70,229,0.4)] mb-8 md:mb-12">
                <Rocket size={48} className="md:w-16 md:h-16 animate-float" />
              </div>
              <h1 className="text-5xl md:text-8xl font-black tracking-tighter text-slate-900 mb-6 md:mb-8 leading-tight">
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 via-rose-500 to-amber-500">FreelancePortfolio</span>
              </h1>
              <p className="text-xl md:text-2xl text-slate-500 font-medium max-w-md mx-auto">Vibrant tools for elite independent creators.</p>
            </div>

            <div className="bg-white/80 backdrop-blur-3xl p-8 md:p-12 rounded-[3rem] md:rounded-[4rem] shadow-2xl border border-white w-full">
              <div className="flex gap-2 md:gap-4 mb-8 md:mb-12 p-1.5 md:p-2 bg-slate-100/50 rounded-[1.5rem] md:rounded-[2rem]">
                <button onClick={() => setIsSignUp(false)} className={`flex-1 py-3 md:py-4 rounded-xl md:rounded-2xl text-[10px] md:text-xs font-black uppercase tracking-[0.2em] transition-all ${!isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>Sign In</button>
                <button onClick={() => setIsSignUp(true)} className={`flex-1 py-3 md:py-4 rounded-xl md:rounded-2xl text-[10px] md:text-xs font-black uppercase tracking-[0.2em] transition-all ${isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>Join</button>
              </div>

              {errorMessage && <div className="mb-6 md:mb-8 p-4 md:p-6 bg-rose-50 border border-rose-100 text-rose-600 rounded-2xl md:rounded-3xl text-[10px] md:text-xs font-bold uppercase flex items-center gap-3"><AlertTriangle size={16}/>{errorMessage}</div>}
              {successMessage && <div className="mb-6 md:mb-8 p-4 md:p-6 bg-emerald-50 border border-emerald-100 text-emerald-600 rounded-2xl md:rounded-3xl text-[10px] md:text-xs font-bold uppercase flex items-center gap-3"><UserCheck size={16}/>{successMessage}</div>}

              <form onSubmit={handleAuth} className="space-y-4 md:space-y-6">
                {isSignUp && (
                  <input type="text" required value={loginName} onChange={(e) => setLoginName(e.target.value)} className="w-full px-6 md:px-8 py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-lg md:text-xl" placeholder="Full Name"/>
                )}
                <input type="email" required value={loginEmail} onChange={(e) => setLoginEmail(e.target.value)} className="w-full px-6 md:px-8 py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-lg md:text-xl" placeholder="Email Address"/>
                <div className="relative">
                  <input type={showPass ? "text" : "password"} required value={loginPass} onChange={(e) => setLoginPass(e.target.value)} className="w-full px-6 md:px-8 py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-lg md:text-xl" placeholder="Password"/>
                  <button type="button" onClick={() => setShowPass(!showPass)} className="absolute inset-y-0 right-6 md:right-8 text-slate-300 hover:text-indigo-600">{showPass ? <EyeOff size={20}/> : <Eye size={20}/>}</button>
                </div>
                <button type="submit" disabled={isAuthLoading} className="w-full bg-gradient-to-r from-indigo-600 to-rose-600 text-white py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] font-black uppercase tracking-[0.3em] text-xs md:text-sm shadow-xl hover:shadow-indigo-500/40 transition-all">
