} from 'lucide-react';

export default function App() {
  const [state, setState] = useState<AppState>({
    view: 'login',
    data: INITIAL_DATA,
    theme: 'minimal',
  });

  const [isInitializing, setIsInitializing] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [isSignUp, setIsSignUp] = useState(false);
  const [loginName, setLoginName] = useState('');
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [isPublishing, setIsPublishing] = useState(false);
  const [hasPublished, setHasPublished] = useState(false);
  const [copied, setCopied] = useState(false);

  const [showAuthModal, setShowAuthModal] = useState(false);
  const [pendingAction, setPendingAction] = useState<'theme-selection' | 'preview' | null>(null);

  const isInitialLoad = useRef(true);

  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') throw error;

      if (data && data.content) {
        const mergedData: PortfolioData = {
          ...INITIAL_DATA,
          ...data.content,
          skills: data.content.skills || [],
          projects: data.content.projects || [],
          qualifications: data.content.qualifications || [],
          certifications: data.content.certifications || [],
          socials: { ...INITIAL_DATA.socials, ...(data.content.socials || {}) }
        };

        setState(prev => ({
          ...prev,
          data: mergedData,
          theme: (data.theme as Theme) || 'minimal'
        }));
        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 2000);
      }
    } catch (err: any) {
      console.error("Fetch error:", err);
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
    }
  };

  useEffect(() => {
    const checkSession = async () => {
      const params = new URLSearchParams(window.location.search);
      const shared = params.get('p');

      if (shared) {
        try {
          const decoded = JSON.parse(decodeURIComponent(escape(atob(shared))));
          if (decoded.data) {
            setState(prev => ({
              ...prev,
              data: decoded.data,
              theme: decoded.theme || 'minimal',
              view: 'preview'
            }));
            setIsInitializing(false);
            return;
          }
        } catch (e) {
          console.error("Decode error", e);
        }
      }

      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);
        await fetchUserPortfolio(session.user.id);
        setState(prev => ({ ...prev, view: 'landing' }));
      }
      setIsInitializing(false);
    };

    checkSession();
  }, []);

  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session) {
        const prevUserId = userId;
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);

        if (event === 'SIGNED_IN' && prevUserId !== session.user.id) {
          await fetchUserPortfolio(session.user.id);

          setState(prev => {
            if (pendingAction === 'theme-selection') return { ...prev, view: 'theme-selection' };
            if (pendingAction === 'preview') return { ...prev, view: 'preview' };
            if (prev.view === 'login') return { ...prev, view: 'landing' };
            return prev;
          });

          setPendingAction(null);
          setShowAuthModal(false);
        }
      } else {
        setUserId(null);
        setUserEmail(null);
        isInitialLoad.current = true;
      }
    });

    return () => subscription.unsubscribe();
  }, [userId, pendingAction]);

  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'preview') return;

    const timer = setTimeout(() => {
      performSync();
    }, 2500);

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const performSync = async () => {
    if (!userId) return;
    setSyncStatus('syncing');
    try {
      const { error } = await supabase.from('portfolios').upsert({
        user_id: userId,
        content: state.data,
        theme: state.theme,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id' });

      if (error) throw error;
      setSyncStatus('synced');
      setTimeout(() => setSyncStatus('idle'), 3000);
      return true;
    } catch (err: any) {
      setSyncStatus('error');
      return false;
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
          options: { data: { full_name: loginName } }
        });
        if (error) throw error;
        setSuccessMessage("Account created! Check email to verify.");
        setIsSignUp(false);
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      setErrorMessage(err.message || "Auth failed.");
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
  };

  const updateData = (data: PortfolioData) => setState(prev => ({ ...prev, data }));
  const setTheme = (theme: Theme) => setState(prev => ({ ...prev, theme }));

  const handleShare = () => {
    const payload = btoa(unescape(encodeURIComponent(JSON.stringify({ data: state.data, theme: state.theme }))));
    const url = `${window.location.origin}${window.location.pathname}?p=${payload}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>${state.data.fullName || 'Portfolio'}</title><script src="https://cdn.tailwindcss.com"></script><link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;700;800&display=swap" rel="stylesheet"><style>body{font-family:'Plus Jakarta Sans',sans-serif;}</style></head><body class="bg-slate-50 min-h-screen p-6 md:p-20"><div class="max-w-4xl mx-auto bg-white p-10 md:p-16 rounded-[3rem] shadow-2xl"><h1 class="text-5xl font-black mb-4">${state.data.fullName}</h1><p class="text-xl text-slate-500 mb-10 font-medium">${state.data.tagline}</p><div class="prose prose-slate lg:prose-xl">${state.data.about.replace(/\n/g, '<br>')}</div><div class="mt-16 grid grid-cols-1 md:grid-cols-2 gap-8">${state.data.projects.map(p => `<div class="p-8 bg-slate-50 rounded-3xl border border-slate-100"><h3 class="text-2xl font-black mb-2">${p.title}</h3><p class="text-slate-500 mb-6">${p.description}</p>${p.link ? `<a href="${p.link}" target="_blank" class="text-indigo-600 font-black uppercase text-[10px] tracking-widest">Explore Project →</a>` : ''}</div>`).join('')}</div></div><div class="text-center py-10 text-[10px] font-black uppercase tracking-widest text-slate-300">Generated by FreelancePortfolio</div></body></html>`;
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${state.data.fullName.replace(/\s+/g, '_')}_Portfolio.html`;
    a.click();
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    const success = await performSync();
    if (success) setHasPublished(true);
    setIsPublishing(false);
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-20 h-20 md:w-24 md:h-24 bg-gradient-to-tr from-indigo-600 via-purple-600 to-rose-600 text-white rounded-3xl flex items-center justify-center animate-bounce shadow-2xl shadow-indigo-200">
          <Rocket size={40} className="md:w-12 md:h-12" />
        </div>
        <p className="mt-8 text-xs md:text-sm font-black uppercase tracking-[0.4em] text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-rose-600 animate-pulse text-center">Initializing Portal</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen selection:bg-rose-100 selection:text-rose-900">
      {state.view === 'login' ? (
        <div className="min-h-screen flex items-center justify-center p-4 md:p-6 relative overflow-hidden">
          <div className="max-w-xl w-full z-10 flex flex-col items-center">
            <div className="text-center mb-8 md:mb-16 px-4">
              <div className="inline-flex items-center justify-center w-24 h-24 md:w-32 md:h-32 bg-gradient-to-tr from-indigo-600 via-rose-600 to-amber-500 text-white rounded-[2.5rem] md:rounded-[3rem] shadow-[0_32px_64px_-16px_rgba(79,70,229,0.4)] mb-8 md:mb-12">
                <Rocket size={48} className="md:w-16 md:h-16 animate-float" />
              </div>
              <h1 className="text-5xl md:text-8xl font-black tracking-tighter text-slate-900 mb-6 md:mb-8 leading-tight">
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 via-rose-500 to-amber-500">FreelancePortfolio</span>
              </h1>
              <p className="text-xl md:text-2xl text-slate-500 font-medium max-w-md mx-auto">Vibrant tools for elite independent creators.</p>
            </div>

            <div className="bg-white/80 backdrop-blur-3xl p-8 md:p-12 rounded-[3rem] md:rounded-[4rem] shadow-2xl border border-white w-full">
              <div className="flex gap-2 md:gap-4 mb-8 md:mb-12 p-1.5 md:p-2 bg-slate-100/50 rounded-[1.5rem] md:rounded-[2rem]">
                <button onClick={() => setIsSignUp(false)} className={`flex-1 py-3 md:py-4 rounded-xl md:rounded-2xl text-[10px] md:text-xs font-black uppercase tracking-[0.2em] transition-all ${!isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>Sign In</button>
                <button onClick={() => setIsSignUp(true)} className={`flex-1 py-3 md:py-4 rounded-xl md:rounded-2xl text-[10px] md:text-xs font-black uppercase tracking-[0.2em] transition-all ${isSignUp ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>Join</button>
              </div>

              {errorMessage && <div className="mb-6 md:mb-8 p-4 md:p-6 bg-rose-50 border border-rose-100 text-rose-600 rounded-2xl md:rounded-3xl text-[10px] md:text-xs font-bold uppercase flex items-center gap-3"><AlertTriangle size={16}/>{errorMessage}</div>}
              {successMessage && <div className="mb-6 md:mb-8 p-4 md:p-6 bg-emerald-50 border border-emerald-100 text-emerald-600 rounded-2xl md:rounded-3xl text-[10px] md:text-xs font-bold uppercase flex items-center gap-3"><UserCheck size={16}/>{successMessage}</div>}

              <form onSubmit={handleAuth} className="space-y-4 md:space-y-6">
                {isSignUp && (
                  <input type="text" required value={loginName} onChange={(e) => setLoginName(e.target.value)} className="w-full px-6 md:px-8 py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-lg md:text-xl" placeholder="Full Name"/>
                )}
                <input type="email" required value={loginEmail} onChange={(e) => setLoginEmail(e.target.value)} className="w-full px-6 md:px-8 py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-lg md:text-xl" placeholder="Email Address"/>
                <div className="relative">
                  <input type={showPass ? "text" : "password"} required value={loginPass} onChange={(e) => setLoginPass(e.target.value)} className="w-full px-6 md:px-8 py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] border border-slate-100 bg-white/50 focus:bg-white focus:ring-8 focus:ring-indigo-500/5 outline-none transition-all font-semibold text-lg md:text-xl" placeholder="Password"/>
                  <button type="button" onClick={() => setShowPass(!showPass)} className="absolute inset-y-0 right-6 md:right-8 text-slate-300 hover:text-indigo-600">{showPass ? <EyeOff size={20}/> : <Eye size={20}/>}</button>
                </div>
                <button type="submit" disabled={isAuthLoading} className="w-full bg-gradient-to-r from-indigo-600 to-rose-600 text-white py-4 md:py-6 rounded-[1.5rem] md:rounded-[2rem] font-black uppercase tracking-[0.3em] text-xs md:text-sm shadow-xl hover:shadow-indigo-500/40 transition-all">
                  {isAuthLoading ? <Loader2 size={24} className="animate-spin mx-auto"/> : (isSignUp ? "INITIALIZE" : "AUTHENTICATE")}
                </button>
