                <div className="mb-12 md:mb-24">
                  <h2 className="text-4xl md:text-7xl font-black text-slate-900 mb-4 md:mb-6 tracking-tighter italic uppercase flex items-center gap-6"><Palette size={32} className="text-indigo-600 md:w-16 md:h-16" />Visual Aesthetic</h2>
