                  <div className="flex items-center gap-4 md:gap-6 bg-white px-6 md:px-8 py-4 md:py-6 rounded-2xl md:rounded-[2.5rem] border border-slate-100 shadow-sm w-full md:w-auto">
                    <div className="w-10 h-10 md:w-14 md:h-14 bg-emerald-50 text-emerald-600 rounded-xl md:rounded-2xl flex items-center justify-center animate-pulse"><Activity size={24}/></div>
                    <div><span className="text-[10px] md:text-[11px] font-black uppercase tracking-[0.3em] text-slate-400">Live Status</span><p className="text-xs md:text-sm font-black text-slate-900 uppercase italic">Authenticated</p></div>
