                    <div className="w-16 h-16 md:w-20 md:h-20 bg-indigo-50 text-indigo-600 rounded-2xl md:rounded-[2rem] flex items-center justify-center mb-8 md:mb-10 shadow-sm"><Edit3 size={32} className="md:w-10 md:h-10"/></div>
                    <h3 className="text-2xl md:text-3xl font-black uppercase italic mb-3 md:mb-4">Edit Core</h3>
                    <p className="text-slate-400 text-sm md:text-base">Refine your projects and narrative.</p>
