                  <button onClick={() => setState(prev => ({...prev, view: 'theme-selection'}))} className="group p-8 md:p-12 bg-white rounded-[2rem] md:rounded-[3rem] border-4 border-transparent hover:border-rose-500 shadow-2xl transition-all text-left">
