            <div class="flex flex-wrap justify-center gap-6 md:gap-10 text-sm font-semibold opacity-80">
                ${data.email ? `<div class="flex items-center gap-2"><span>Email:</span><a href="mailto:${data.email}" class="underline">${data.email}</a></div>` : ''}
