                        <button onClick={handleShare} className={`flex-1 md:flex-none px-4 md:px-10 py-4 md:py-5 rounded-xl md:rounded-[1.8rem] text-[10px] md:text-sm font-black uppercase shadow-xl transition-all ${copied ? 'bg-emerald-500 text-white' : 'bg-indigo-600 text-white'}`}>
                          {copied ? <Check size={20}/> : <Share2 size={20}/>} {copied ? 'COPIED' : 'SHARE'}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
                <div className="min-h-screen"><PortfolioPreview data={state.data} theme={state.theme} /></div>
                <div className="h-40 md:h-64"></div>
              </div>
            )}
          </main>

          {state.view !== 'preview' && (
            <footer className="bg-white border-t border-slate-100 py-16 md:py-32 px-6 md:px-8 text-center mt-auto">
              <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-center justify-between gap-10 md:gap-16">
                <div className="flex items-center gap-4 md:gap-5">
                  <div className="w-10 h-10 md:w-14 md:h-14 bg-gradient-to-tr from-indigo-600 to-purple-600 text-white rounded-xl md:rounded-[1.2rem] flex items-center justify-center shadow-xl"><rocket size={24}/></div>
                  <h1 className="text-xl md:text-3xl font-black tracking-tighter leading-none text-slate-900 italic">FreelancePortfolio</h1>
                </div>
                <div className="flex flex-col sm:flex-row items-center gap-4 md:gap-12">
                  <div className="flex items-center gap-2 md:gap-3 text-[10px] md:text-[11px] font-black uppercase tracking-[0.3em] md:tracking-[0.4em] text-slate-400"><ShieldCheck size={16} className="text-emerald-500"/> AES-256 ENCRYPTION</div>
                </div>
              </div>
            </footer>
          )}

          {showAuthModal && (
            <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
              <div className="max-w-md w-full bg-white rounded-[2.5rem] md:rounded-[3rem] p-8 md:p-12 shadow-2xl relative">
                <button onClick={() => {setShowAuthModal(false); setPendingAction(null);}} className="absolute top-6 md:top-10 right-6 md:right-10 text-gray-400 hover:text-indigo-600"><X size={24}/></button>
                <div className="text-center mb-8 md:mb-10"><Lock className="mx-auto text-indigo-600 mb-4 md:mb-6" size={40}/><h2 className="text-3xl md:text-4xl font-black tracking-tighter">Secure Account</h2></div>
                <form onSubmit={handleAuth} className="space-y-4 md:space-y-6">
                  <input type="email" required value={loginEmail} onChange={(e) => setLoginEmail(e.target.value)} className="w-full px-6 md:px-8 py-4 md:py-5 rounded-2xl md:rounded-[2rem] border border-slate-100 bg-gray-50 focus:bg-white outline-none transition-all font-semibold" placeholder="Email"/>
                  <input type="password" required value={loginPass} onChange={(e) => setLoginPass(e.target.value)} className="w-full px-6 md:px-8 py-4 md:py-5 rounded-2xl md:rounded-[2rem] border border-slate-100 bg-gray-50 focus:bg-white outline-none transition-all font-semibold" placeholder="Password"/>
                  <button type="submit" className="w-full bg-indigo-600 text-white py-4 md:py-5 rounded-2xl md:rounded-[2rem] font-black uppercase tracking-widest shadow-xl text-xs md:text-sm">AUTHENTICATE</button>
                </form>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Category, Theme, PortfolioData } from './types';
import { CATEGORIES, INITIAL_DATA } from './constants';
import CategoryCard from './components/CategoryCard';
import EditorForm from './components/EditorForm';
import PortfolioPreview from './components/PortfolioPreview';
import { supabase } from './services/supabase';
import { 
  ArrowLeft, 
  Sparkles, 
  Rocket, 
  Monitor, 
  Eye, 
  EyeOff,
  Download,
  Share2,
  Check,
  Zap,
  Lock,
  Mail,
  ArrowRight,
  ShieldCheck,
  Loader2,
  LogOut,
  AlertTriangle,
  UserCheck,
  Palette,
  LayoutDashboard,
  Edit3,
  User,
  Activity,
  X,
  ChevronRight
} from 'lucide-react';

export default function App() {
  const [state, setState] = useState<AppState>({
    view: 'login',
    data: INITIAL_DATA,
    theme: 'minimal',
  });

  const [isInitializing, setIsInitializing] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [isSignUp, setIsSignUp] = useState(false);
  const [loginName, setLoginName] = useState('');
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [isAuthLoading, setIsAuthLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'synced' | 'error'>('idle');
  const [isPublishing, setIsPublishing] = useState(false);
  const [hasPublished, setHasPublished] = useState(false);
  const [copied, setCopied] = useState(false);

  const [showAuthModal, setShowAuthModal] = useState(false);
  const [pendingAction, setPendingAction] = useState<'theme-selection' | 'preview' | null>(null);

  const isInitialLoad = useRef(true);

  const fetchUserPortfolio = async (uid: string) => {
    setSyncStatus('syncing');
    try {
      const { data, error } = await supabase
        .from('portfolios')
        .select('content, theme')
        .eq('user_id', uid)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') throw error;

      if (data && data.content) {
        const mergedData: PortfolioData = {
          ...INITIAL_DATA,
          ...data.content,
          skills: data.content.skills || [],
          projects: data.content.projects || [],
          qualifications: data.content.qualifications || [],
          certifications: data.content.certifications || [],
          socials: { ...INITIAL_DATA.socials, ...(data.content.socials || {}) }
        };

        setState(prev => ({
          ...prev,
          data: mergedData,
          theme: (data.theme as Theme) || 'minimal'
        }));
        setSyncStatus('synced');
        setTimeout(() => setSyncStatus('idle'), 2000);
      }
    } catch (err: any) {
      console.error("Fetch error:", err);
      setSyncStatus('error');
    } finally {
      isInitialLoad.current = false;
    }
  };

  useEffect(() => {
    const checkSession = async () => {
      try {
        const params = new URLSearchParams(window.location.search);
        const shared = params.get('p');

        if (shared) {
          try {
            const decoded = JSON.parse(decodeURIComponent(escape(atob(shared))));
            if (decoded.data) {
              setState(prev => ({
                ...prev,
                data: decoded.data,
                theme: decoded.theme || 'minimal',
                view: 'preview'
              }));
              return;
            }
          } catch (e) {
            console.error("Decode error", e);
          }
        }

        const { data: { session } } = await supabase.auth.getSession();
        if (session) {
          setUserId(session.user.id);
          setUserEmail(session.user.email ?? null);
          await fetchUserPortfolio(session.user.id);
          setState(prev => ({ ...prev, view: 'landing' }));
        }
      } catch (err) {
        console.error("Session check failed", err);
      } finally {
        setIsInitializing(false);
      }
    };

    checkSession();
  }, []);

  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
      if (session) {
        const prevUserId = userId;
        setUserId(session.user.id);
        setUserEmail(session.user.email ?? null);

        if (event === 'SIGNED_IN' && prevUserId !== session.user.id) {
          await fetchUserPortfolio(session.user.id);

          setState(prev => {
            if (pendingAction === 'theme-selection') return { ...prev, view: 'theme-selection' };
            if (pendingAction === 'preview') return { ...prev, view: 'preview' };
            if (prev.view === 'login') return { ...prev, view: 'landing' };
            return prev;
          });

          setPendingAction(null);
          setShowAuthModal(false);
        }
      } else {
        setUserId(null);
        setUserEmail(null);
        isInitialLoad.current = true;
      }
    });

    return () => subscription.unsubscribe();
  }, [userId, pendingAction]);

  useEffect(() => {
    if (isInitialLoad.current || !userId || state.view === 'preview') return;

    const timer = setTimeout(() => {
      performSync();
    }, 2500);

    return () => clearTimeout(timer);
  }, [state.data, state.theme, userId, state.view]);

  const performSync = async () => {
    if (!userId) return;
    setSyncStatus('syncing');
    try {
      const { error } = await supabase.from('portfolios').upsert({
        user_id: userId,
        content: state.data,
        theme: state.theme,
        updated_at: new Date().toISOString(),
      }, { onConflict: 'user_id' });

      if (error) throw error;
      setSyncStatus('synced');
      setTimeout(() => setSyncStatus('idle'), 3000);
      return true;
    } catch (err: any) {
      setSyncStatus('error');
      return false;
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsAuthLoading(true);
    setErrorMessage(null);
    setSuccessMessage(null);

    try {
      if (isSignUp) {
        const { error } = await supabase.auth.signUp({
          email: loginEmail,
          password: loginPass,
          options: { data: { full_name: loginName } }
        });
        if (error) throw error;
        setSuccessMessage("Account created! Check email to verify.");
        setIsSignUp(false);
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: loginEmail,
          password: loginPass,
        });
        if (error) throw error;
      }
    } catch (err: any) {
      setErrorMessage(err.message || "Auth failed.");
    } finally {
      setIsAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setState(prev => ({ ...prev, view: 'login', data: INITIAL_DATA }));
  };

  const updateData = (data: PortfolioData) => setState(prev => ({ ...prev, data }));
  const setTheme = (theme: Theme) => setState(prev => ({ ...prev, theme }));

  const handleShare = () => {
    const payload = btoa(unescape(encodeURIComponent(JSON.stringify({ data: state.data, theme: state.theme }))));
    const url = `${window.location.origin}${window.location.pathname}?p=${payload}`;
    navigator.clipboard.writeText(url);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const { data, theme } = state;
    const themeConfigs: Record<Theme, { body: string; card: string; title: string; accent: string; font: string; skill: string; sectionHeader: string }> = {
      minimal: {
        body: 'bg-white text-gray-800',
        card: 'bg-gray-50 border border-gray-100 p-8 rounded-2xl',
        title: 'text-5xl md:text-6xl font-black mb-4 tracking-tight',
        accent: 'text-indigo-600',
        font: "'Plus Jakarta Sans', sans-serif",
        skill: 'bg-gray-100 text-gray-600 px-4 py-2 rounded-xl text-sm font-bold',
        sectionHeader: 'text-xs font-black uppercase tracking-[0.4em] opacity-40 mb-10'
      },
      modern: {
        body: 'bg-slate-950 text-slate-100',
        card: 'bg-slate-900 border border-slate-800 p-8 rounded-3xl',
        title: 'text-6xl md:text-7xl font-black mb-4 bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-cyan-400',
        accent: 'text-indigo-400',
        font: "'Plus Jakarta Sans', sans-serif",
        skill: 'bg-slate-800 text-slate-300 px-4 py-2 rounded-xl text-sm font-bold',
        sectionHeader: 'text-xs font-black uppercase tracking-[0.4em] opacity-40 mb-10'
      },
      glass: {
        body: 'bg-indigo-600 text-white',
        card: 'bg-white/10 backdrop-blur-xl border border-white/20 p-8 rounded-[2.5rem]',
        title: 'text-6xl md:text-7xl font-bold mb-4 drop-shadow-xl',
        accent: 'text-white',
        font: "'Plus Jakarta Sans', sans-serif",
        skill: 'bg-white/20 text-white px-4 py-2 rounded-xl text-sm font-bold',
        sectionHeader: 'text-xs font-black uppercase tracking-[0.4em] opacity-40 mb-10'
      },
      bold: {
        body: 'bg-yellow-400 text-black',
        card: 'bg-white border-4 border-black p-8 rounded-none shadow-[8px_8px_0px_0px_rgba(0,0,0,1)]',
        title: 'text-7xl md:text-8xl font-black uppercase tracking-tighter mb-4',
        accent: 'text-black font-bold border-b-4 border-black',
        font: "'Plus Jakarta Sans', sans-serif",
        skill: 'bg-black text-white px-4 py-2 font-bold uppercase tracking-widest text-xs',
        sectionHeader: 'text-xl font-black uppercase tracking-tighter mb-10 bg-black text-yellow-400 inline-block px-4 py-1'
      },
      classic: {
        body: 'bg-stone-50 text-stone-900',
        card: 'border-b border-stone-200 py-12',
        title: 'text-6xl md:text-7xl font-serif italic mb-6',
        accent: 'text-stone-900 italic border-b border-stone-900',
        font: "'Playfair Display', serif",
        skill: 'border-stone-300 border-b italic px-4 py-1 text-sm font-medium',
        sectionHeader: 'text-xs font-black uppercase tracking-[0.4em] opacity-40 mb-10 border-b border-stone-200 pb-2'
      },
      vibrant: {
        body: 'bg-rose-50 text-rose-950',
        card: 'bg-white rounded-[3rem] p-10 border-4 border-rose-100 shadow-xl',
        title: 'text-6xl md:text-7xl font-black italic tracking-tighter text-rose-600 mb-4',
        accent: 'text-rose-600 font-bold',
        font: "'Plus Jakarta Sans', sans-serif",
        skill: 'bg-rose-100 text-rose-600 px-4 py-2 rounded-full text-xs font-bold',
        sectionHeader: 'text-xs font-black uppercase tracking-[0.4em] text-rose-800/40 mb-10'
      }
    };

    const config = themeConfigs[theme];

    const socialsHtml = Object.entries(data.socials)
      .filter(([_, val]) => val)
      .map(([key, val]) => `<a href="${val}" target="_blank" class="opacity-60 hover:opacity-100 transition-opacity font-bold uppercase tracking-widest text-[10px] underline decoration-current decoration-2 underline-offset-4">${key}</a>`)
      .join(' ');

    const html = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${data.fullName || 'Professional Portfolio'}</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;700;800&family=Playfair+Display:ital,wght@0,400..900;1,400..900&display=swap" rel="stylesheet">
    <style>
        body { font-family: ${config.font}; scroll-behavior: smooth; }
        .prose br { margin-bottom: 1rem; }
    </style>
</head>
<body class="${config.body} min-h-screen">
    <div class="max-w-5xl mx-auto px-6 py-20 md:py-32">
        <header class="mb-24 text-center">
            <h1 class="${config.title}">${data.fullName || 'Creative Talent'}</h1>
            <p class="text-xl md:text-2xl opacity-60 font-medium max-w-2xl mx-auto leading-relaxed mb-10">${data.tagline || 'Innovation through creativity.'}</p>

            <div class="flex flex-wrap justify-center gap-6 md:gap-10 text-sm font-semibold opacity-80">
                ${data.email ? `<div class="flex items-center gap-2"><span>Email:</span><a href="mailto:${data.email}" class="underline">${data.email}</a></div>` : ''}
                ${data.location ? `<div class="flex items-center gap-2"><span>Location:</span><span>${data.location}</span></div>` : ''}
            </div>

            <div class="mt-8 flex justify-center gap-6">
                ${socialsHtml}
            </div>
        </header>

        <section class="mb-32">
            <h2 class="${config.sectionHeader}">Narrative</h2>
            <div class="text-2xl md:text-3xl font-medium leading-relaxed opacity-90 whitespace-pre-wrap">
                ${data.about || 'A dedicated professional bringing unique perspectives to every project.'}
            </div>
        </section>

        ${data.skills.length > 0 ? `
        <section class="mb-32">
            <h2 class="${config.sectionHeader}">Mastery & Arsenal</h2>
            <div class="flex flex-wrap gap-3">
                ${data.skills.map(s => `<span class="${config.skill}">${s.name} <span class="opacity-50 text-[10px] ml-1">${s.level}%</span></span>`).join('')}
            </div>
        </section>` : ''}

        ${data.qualifications.length > 0 || data.certifications.length > 0 ? `
        <section class="mb-32 grid grid-cols-1 md:grid-cols-2 gap-16">
            ${data.qualifications.length > 0 ? `
            <div>
                <h2 class="${config.sectionHeader}">Education</h2>
                <div class="space-y-8">
                    ${data.qualifications.map(q => `
                    <div>
                        <div class="flex justify-between items-start mb-1">
