                            <span class="text-[10px] font-black uppercase tracking-widest opacity-40">${q.year}</span>
                        </div>
                        <p class="opacity-60 font-medium">${q.institution}</p>
                    </div>`).join('')}
                </div>
            </div>` : ''}
            ${data.certifications.length > 0 ? `
            <div>
                <h2 class="${config.sectionHeader}">Certifications</h2>
                <div class="space-y-8">
                    ${data.certifications.map(c => `
                    <div>
                        <div class="flex justify-between items-start mb-1">
                            <h3 class="text-xl font-black">${c.name}</h3>
                            <span class="text-[10px] font-black uppercase tracking-widest opacity-40">${c.date}</span>
                        </div>
                        <p class="opacity-60 font-medium">${c.issuer}</p>
                        ${c.link ? `<a href="${c.link}" target="_blank" class="text-[10px] font-bold uppercase underline mt-2 inline-block">Verify →</a>` : ''}
                    </div>`).join('')}
                </div>
            </div>` : ''}
        </section>` : ''}

        <section class="mb-32">
            <h2 class="${config.sectionHeader}">Featured Works</h2>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-10">
                ${data.projects.map(p => `
                <div class="${config.card}">
                    <h3 class="text-2xl font-black mb-3">${p.title}</h3>
                    <p class="opacity-60 mb-8 leading-relaxed">${p.description}</p>
                    ${p.link ? `<a href="${p.link}" target="_blank" class="${config.accent} uppercase text-[10px] tracking-widest font-black underline underline-offset-4 decoration-2">Explore Project →</a>` : ''}
                </div>`).join('')}
            </div>
        </section>

        <footer class="pt-20 border-t border-current opacity-10 text-center">
            <div class="text-[10px] font-black uppercase tracking-[0.5em]">© ${new Date().getFullYear()} ${data.fullName} • Identity Portal Export</div>
        </footer>
    </div>
</body>
</html>`;

    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${data.fullName.replace(/\s+/g, '_')}_Portfolio_Export.html`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handlePublish = async () => {
    setIsPublishing(true);
    const success = await performSync();
    if (success) setHasPublished(true);
    setIsPublishing(false);
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center p-6">
        <div className="w-20 h-20 md:w-24 md:h-24 bg-gradient-to-tr from-indigo-600 via-purple-600 to-rose-600 text-white rounded-3xl flex items-center justify-center animate-bounce shadow-2xl shadow-indigo-200">
          <Rocket size={40} className="md:w-12 md:h-12" />
        </div>
        <p className="mt-8 text-xs md:text-sm font-black uppercase tracking-[0.4em] text-transparent bg-clip-text bg-gradient-to-r from-indigo-600 to-rose-600 animate-pulse text-center">Initializing Portal</p>
      </div>
    );
  }

