                 Max 10 words. Return ONLY the tagline.`,
    });
    return response.text?.trim() || `Crafting excellence in ${category}.`;
  } catch (error) {
    console.error("Gemini Error:", error);
    return `Specializing in ${category}.`;
  }
};

