              setState(prev => ({
                ...prev,
                data: decoded.data,
                theme: decoded.theme || 'minimal',
                view: 'preview'
              }));
            }
          } catch (e) {
            console.error("Link decode error", e);
          }
        }
      } catch (err) {
        console.error("Init check failed", err);
      } finally {
        setIsInitializing(false);
      }
    };

    checkSharedLink();
  }, []);

